const CHAPTERS: VizChapter[] = [{"id":"bd-ch01","subj":"bigdata","title":"Hadoop 生态与 HDFS 架构","summary":"从单机到分布式的动机（容量、吞吐、容错）；HDFS 的 NameNode/DataNode/Block 与元数据设计；副本放置策略与机架感知；edits log 与 fsimage 的合并（checkpoint）；文件写入的流水线复制与读取…","concepts":[{"id":"bd-ch01/01-hadoop-ecosystem","file":"01-hadoop-ecosystem.md","title":"Hadoop 生态全景与组件分工","kind":"flow","secs":[{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"BLOCK = 128 * 1024 * 1024\nclass INode:\n    def __init__(self, path):\n        self.path = path\n        self.blocks = []\n        self.replicas = {}\ndns = [\"dn1\", \"dn2\", \"dn3\"]\ndef create(path, size, rep=3):\n    n = INode(path)\n…"}},{"h":"二、从单机到分布式的动机：容量、吞吐、容错","s":"（中立陈述）单机文件系统（ext4/xfs）受限于单盘容量、单机能挂载的盘数、以及单条总线的 IO 带宽；更致命的是「单机故障 = 数据不可用甚至丢失」。分布式文件系统把文件分块（block）后打散到成百上千台廉价机器，用「分而治之 +…","c":null}]},{"id":"bd-ch01/02-hdfs-architecture","file":"02-hdfs-architecture.md","title":"NameNode 元数据与命名空间（文件系统的大脑）","kind":"stack","secs":[{"h":"二、DataNode 与块存储（真正搬砖的劳工）","s":"（中立陈述）DataNode 在本地磁盘以块（block）文件 + 校验和（meta）文件的形式存储数据；它周期性向 NameNode 发送心跳（默认 3s）与块报告（默认 6h，增量更频繁）；收到 NameNode 的指令（复制、删除…","c":null}]},{"id":"bd-ch01/03-replica-rack-checkpoint","file":"03-replica-rack-checkpoint.md","title":"副本放置策略与机架感知（rack awareness）","kind":"flow","secs":[{"h":"二、fsimage / edits 与 checkpoint（安全模式）","s":"（中立陈述）NameNode 启动时先加载 fsimage（命名空间快照），再重放 edits（增量日志）得到最新状态。随运行 edits 越来越大，Secondary NameNode（或 Standby 的 Checkpointer…","c":null}]},{"id":"bd-ch01/04-write-pipeline-read","file":"04-write-pipeline-read.md","title":"写入的流水线复制（pipeline）","kind":"timeline","secs":[{"h":"二、读取、短路读与小文件问题","s":"（中立陈述）HDFS 读文件时，客户端先向 NameNode 拿到「文件的块列表及每块所在 DataNode」，然后就近（同节点 > 同机架 > 跨机架）挑一个副本直接读；当客户端与数据同机时可用 short-circuit read（…","c":null}]},{"id":"bd-ch01/05-hdfs-practical-recipes","file":"05-hdfs-practical-recipes.md","title":"§5 bd-ch01 实战手记：凯喵带你把 HDFS 用「挂」","kind":"flow","secs":[{"h":"现场一：副本因子设成 1 省空间，丢块一起丢","s":"凯喵为了「省存储」把 dfs.replication=1，结果一个 DataNode 硬盘坏掉，直接丢了一整批块，作业全红。默认 3 副本是「同机架 2 + 跨机架 1」，能扛整机架断电。生产保持 ≥3；冷数据改用 Erasure Co…","c":{"lang":"xml","code":"<!-- hdfs-site.xml -->\n<property>\n  <name>dfs.replication</name>\n  <value>3</value>   <!-- ✅ 生产至少 3 -->\n</property>\n<!-- 冷数据改用 EC，省空间且仍可恢复 -->\n<property>\n  <name>dfs.namenode.ec.policies.enabled</name>\n  <value>RS-6-3-1024k</value>\n…"}},{"h":"现场二：单 NameNode 不做 checkpoint，重启小时级","s":"凯喵的公司只部署一个 NameNode，又没 SecondaryNameNode，跑了几个月 edits 文件涨到几百 GB。重启时要回放全部 editlog，启动时间从小秒级变成小时级，业务停摆半天。解法：QJM + ZKFC 做 H…","c":{"lang":"bash","code":"# 手动触发 checkpoint（仅 SecondaryNameNode 场景）\nhdfs dfsadmin -saveNamespace\n# 看上次 checkpoint 时间，超时即告警\nhdfs dfsadmin -report | grep -i \"Last\""}},{"h":"现场三：把 SecondaryNameNode 当「热备」是最大误解","s":"凯喵新人以为 SecondaryNameNode 挂了 NameNode 能自动接管——大错。SNN 只做 fsimage + edits 定期合并，减轻 NN 内存压力，不接管服务、不保存最新 edits。真正的热备是 HA 里的 S…","c":{"lang":"text","code":"NameNode        : 接收读写，写 edits，内存维护元数据\nSecondaryNameNode: 周期性 pull edits + fsimage 合并回传（不是备份！）\nStandby NN(HA)  : 实时读共享 edits，随时可切主（这才是热备）"}},{"h":"现场四：小文件海量，NameNode 内存被元数据撑爆","s":"凯喵的爬虫每小时落几百万个几 KB 的小文件，三个月后 NameNode 内存 OOM、集群不可用。HDFS 为每个文件/目录/块在 NN 内存存约 150 字节元数据，小文件多了元数据开销远超数据本身。治理：HAR 归档、HBase/…","c":{"lang":"bash","code":"# 用 HAR 把海量小文件归档成一个大文件\nhadoop archive -archiveName logs.har -p /data/logs /data/archive"}},{"h":"现场五：机架感知没配，跨机架副本失效","s":"凯喵的集群所有 DataNode 被误认为同一机架，3 副本全落在一个机柜。结果那个机柜交换机一挂，整批块不可用。副本放置策略依赖机架感知（net.topology.script 返回每节点的机架路径），否则「同机架 2 + 跨机架 1…","c":{"lang":"xml","code":"<property>\n  <name>net.topology.script.file.name</name>\n  <value>/etc/hadoop/rack-awareness.sh</value>  <!-- 返回 /rack1 之类 -->\n</property>"}},{"h":"现场六：写入流水线中对端慢，整条 pipeline 卡住","s":"凯喵的大文件写入时，一个 DataNode 磁盘 IO 慢，整条 pipeline 吞吐被它拖垮。HDFS 写入是流水线复制（client→DN1→DN2→DN3），任一环节慢都拉低整体。监控各 DN 的 BytesWritten 速率…","c":{"lang":"bash","code":"# 查看各 DN 写入速率，定位慢节点\nhdfs dfsadmin -report"}},{"h":"现场七：安全模式下写数据全部失败","s":"凯喵重启 NN 后程序狂报「NameNode is in safe mode」。安全模式是 NN 启动时的保护态：先等足够比例的块上报（默认 dfs.namenode.safemode.threshold-pct=0.999），确认块齐…","c":{"lang":"bash","code":"hdfs dfsadmin -safemode get      # 查状态\nhdfs dfsadmin -safemode wait     # 脚本里等它退出\n# hdfs dfsadmin -safemode leave  # 仅确认数据齐全后手动退出"}},{"h":"现场八：短路读（short-circuit）没开，本地读也走网络","s":"凯喵的 NodeLocal 任务读本地块却要走 TCP 回路，延迟高。HDFS 支持短路读：client 与 DN 同机时直接读本地文件、绕过网络栈。需配置 dfs.client.read.shortcircuit=true 且 uni…","c":{"lang":"xml","code":"<property>\n  <name>dfs.client.read.shortcircuit</name>\n  <value>true</value>\n</property>\n<property>\n  <name>dfs.domain.socket.path</name>\n  <value>/var/run/hadoop/dn.socket</value>\n</property>"}},{"h":"现场九：块大小设太小，Map 数爆炸","s":"凯喵把 dfs.blocksize 设成 32MB（甚至默认被改），1TB 数据产生几万个块，NN 元数据压力大、Map 任务数爆炸。Hadoop 3 默认 128MB（甚至 256MB），大文件场景块越大、元数据越少、吞吐越高。按文件…","c":{"lang":"xml","code":"<property>\n  <name>dfs.blocksize</name>\n  <value>134217728</value>  <!-- 128 MB，大文件友好 -->\n</property>"}},{"h":"现场十：心跳/块报告超时，误判 DN 死亡触发大量复制","s":"凯喵的 DN 因 GC 停顿太久，NN 在 dfs.namenode.heartbeat.recheck-interval 内没收到心跳，把它标记为 dead，立刻在别的 DN 补副本，网络被打满。调大超时与 heartbeat.int…","c":{"lang":"xml","code":"<property>\n  <name>dfs.namenode.heartbeat.recheck-interval</name>\n  <value>300000</value>  <!-- 5 分钟再判定死亡，避免 GC 抖动误杀 -->\n</property>"}},{"h":"现场十一：回收站默认关，rm -r 直接没","s":"凯喵手滑 hdfs dfs -rm -r /data/tmp，文件瞬间消失不可恢复。HDFS 回收站默认关闭，需开 fs.trash.interval>0，删除的文件先进 /user/.../.Trash，到期才真删。重要目录操作前先确…","c":{"lang":"xml","code":"<property>\n  <name>fs.trash.interval</name>\n  <value>1440</value>  <!-- 1 天保留，误删可救 -->\n</property>"}},{"h":"现场十二：fsimage 从不备份，NN 元数据损坏即全损","s":"凯喵的 NN 元数据目录只在一块盘上，磁盘坏道导致 fsimage 损坏，集群起不来。NN 的元数据是「命根子」，必须：① 配 HA 共享存储（QJM/ZK）；② 定期把 fsimage 备份到异地；③ dfs.namenode.nam…","c":{"lang":"xml","code":"<property>\n  <name>dfs.namenode.name.dir</name>\n  <value>/data/nn,/data2/nn</value>  <!-- 多盘冗余，坏一块不丢 -->\n</property>"}},{"h":"🧑‍💻 程序员视角","s":"副本因子设成 1 省空间，结果一台机器坏就丢块——HDFS 的容错完全建立在副本上，省副本等于放弃可靠性。单 NameNode 不做 checkpoint，edits 无限增长，重启时回放要几小时。把 SecondaryNameNode…","c":null},{"h":"🎓 博士生视角","s":"HDFS 的设计假设是「大文件、顺序读、高吞吐、容忍高延迟」，因此它牺牲了随机写与低延迟。NameNode 把所有元数据放内存，使「文件数」成为硬上限，这也是 Federation（多 NameNode 分片命名空间）与 Ozone（对…","c":null},{"h":"📚 考研者视角","s":"大数据面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"HDFS 默认三副本的放置顺序，下列哪项正确？","stem":"关于 HDFS 默认副本因子为 3 时的放置策略，哪一项符合官方口径？","opts":[{"k":"A","t":"第1副本本地，第2副本同机架，第3副本跨机架"},{"k":"B","t":"第1副本本地，第2副本跨机架，第3副本与第2同机架的另一节点"},{"k":"C","t":"三副本随机分散在三台机器，不区分机架"},{"k":"D","t":"第1副本本地，其余两份都放在与第1同机架的不同节点"}],"ans":"B","why":"官方策略：第1副本在客户端本地节点；第2副本放在不同机架；第3副本放在与第2同机架的另一节点。第2副本即已跨机架，兼顾容灾与写带宽。"},{"kind":"output","q":"计算一个 300MB 文件在默认 128MB 块大小下的块数","stem":"HDFS 默认块大小为 128MB。给定文件大小 300MB，问该文件被切成多少块（最后一块可小于 128MB）？请写出计算结果。","opts":[],"ans":"块数 = ceil(300 / 128) = 3 块","why":"块数 = ceil(文件大小 / 块大小)。300/128 = 2.34，向上取整为 3；前两块各 128MB，第三块 44MB。"},{"kind":"fix_error","q":"找出下列关于 Secondary NameNode 的错误说法并改正","stem":"某教材写道：「Secondary NameNode 是 NameNode 的热备，当 NameNode 宕机时 Secondary NameNode 会自动接管集群，保证高可用。」请指出错误并改正。","opts":[],"ans":"该说法错误","why":"Secondary NameNode 不能接管服务，它只负责周期性合并 fsimage 与 edits。生产高可用必须启用 HA。"},{"kind":"coding","q":"岛屿数量（与集群机架连通域分析思想同源）","stem":"题面与完整描述请见外部链接（合规：只存元数据+链接）。本题用 DFS/BFS 求网格中连通块数量，思想与『判断机架/节点连通域、块副本故障域隔离』同源：把矩阵中的 1 视为连通区域，统计独立连通块个数。","opts":[],"ans":"见外部链接题解","why":"连通分量计数；可与 HDFS 机架拓扑中的『故障域识别』类比理解。"},{"kind":"coding","q":"副本放置：在机架拓扑下实现 fault-domain 隔离放置","stem":"题面与完整描述请见外部仓库（合规：只存元数据+链接）。要求在给定『节点→机架』拓扑下，为某个块的 r 个副本挑选节点，使得任意两副本不共机架（在 r ≤ 机架数时），并尽量让首个副本本地。","opts":[],"ans":"见外部仓库实现","why":"本质是带约束的候选节点剪枝：按拓扑树保证副本落在不同故障域，对应 HDFS 机架感知放置策略。"},{"kind":"choice","q":"HDFS 刚启动后处于安全模式（Safe Mode），原因是什么？","stem":"NameNode 重启后，集群会先进入安全模式（只读不写），直到满足阈值才自动退出。其根本原因是什么？","opts":[{"k":"A","t":"NameNode 在等待所有 DataNode 全部重启完成"},{"k":"B","t":"块到 DataNode 的映射需由 DataNode 块报告动态重建，未收齐前数据完整性无法保证"},{"k":"C","t":"edits 日志损坏需要人工修复"},{"k":"D","t":"HDFS 默认启动就是只读模式，与状态无关"}],"ans":"B","why":"块位置映射不持久化在 fsimage，而是启动后由块报告重建；安全模式是『数据完整性闸门』，待达到最小副本比例的块数达标才退出。"}],"works":[{"h":"Secondary NameNode 是 NameNode 的热备","d":"错。Secondary NameNode 只做 fsimage/edits 的 checkpoint 合并，NameNode 宕机它不能接管服务。真正的热备是 HA 架构（Active/Standby + QJM + ZKFC）。正确写法：把「高可用」与「检查点」两个职责分清，生产环境务必启用 HA，不要用 Secondary Nam…"},{"h":"块到 DataNode 的映射持久化在 fsimage 里","d":"错。fsimage 只存命名空间与「文件→块列表」，块实际存在哪些 DataNode 是 NameNode 启动后由 DataNode 的块报告动态重建的。因此刚启动、块报告没收齐时集群处于安全模式。正确写法：回答「元数据包含哪些内容」时，明确块位置映射是运行时态、非持久化，并由此推出安全模式的存在原因。"},{"h":"三副本放置是「本地 + 同机架 + 跨机架」","d":"错。官方策略是：第 1 副本在客户端本地节点，第 2 副本放在不同机架，第 3 副本放在与第 2 副本同机架的另一节点。第 2 副本即已跨机架，这是兼顾容灾与写带宽的关键。正确写法：按《Hadoop 权威指南》原话背，别把顺序搞反；并说明为何不全放不同机架（避免写放大）。"},{"h":"HDFS 写数据时客户端同时向三个 DataNode 各发一份","d":"错。HDFS 用流水线（pipeline）：客户端只发一份数据，沿 dn1→dn2→dn3 依次推送，ACK 原路返回。这样把客户端的写放大从 O(r) 降到 O(1)。正确写法：讲清 pipeline 的「单发多传」与 ACK 回传机制，以及节点失效时剔除并重选的容错流程。"},{"h":"安全模式（Safe Mode）是一种故障/错误状态","d":"错。它是 NameNode 启动后的保护态：块位置映射未收齐前只读不写，直到满足最小副本比例的块数达到阈值才自动退出。长时间卡住通常是欠副本块过多（节点没起来/磁盘坏），应先排查而非盲目 safemode leave。正确写法：理解它是「数据完整性闸门」，离开需谨慎，避免丢数据。"},{"h":"小文件在 HDFS 上只是『占不满一个块』的小事","d":"错。HDFS 的瓶颈在 NameNode 内存（每文件 ~150B 元数据）与任务/寻址膨胀；百万小文件会让 NameNode 内存暴涨且读放大严重。正确写法：用 HAR、HBase、或合并成 SequenceFile/ORC/Parquet 等列式大文件治理；MapReduce 输入小文件会「一文件一 map」。"},{"h":"小文件直接 put 进 HDFS → NameNode 内存被吃干","d":"bash hdfs dfs -put /logs/2026-10-31/.log /warehouse/raw/ # 几十万个 10KB 小文件 每个文件、每个块、每个副本在 NameNode 里约占 150 字节元数据。1000 万个 10KB 小文件（数据总量才 100GB）就要吃掉约 3GB 堆，DataNode 磁盘还很空，N…"},{"h":"副本因子调成 1 省空间，容错一起没了","d":"dfs.replication=1 时任一 DataNode 掉线就直接丢块；机架感知也失效（默认 3 副本是「同机架 2 + 跨机架 1」，能扛整机架断电）。 生产保持 ≥3；冷数据改用 Erasure Coding（RS-6-3 把 3x 开销降到约 1.5x），代价是恢复时网络与 CPU 更高、且不支持 append。"}],"asks":[{"q":"HDFS 的 NameNode 存什么、不存什么？块到 DataNode 的映射在哪里？","a":"NameNode 只存元数据：命名空间（目录树）、文件到块的映射、以及运行时「块 → DataNode 列表」的映射。 不存文件真实数据，数据在 DataNode 的本地磁盘。关键易错点：块到 DataNode 的映射并不持久化在 fsimage 中，而是 NameNode 启动后由各个 DataNode 的『块报告（block report）』动态重建。 由此推出两个结论：① 刚启动时块报告没收…","fu":["NameNode 内存大约怎么估算（每文件/块约多少字节）？","HA 架构下 Standby 如何实时拿到最新 edits？"],"tag":"通用/阿里"},{"q":"HDFS 默认三副本的放置策略是什么？为什么这样设计而不是三副本全放不同机架？","a":"经典策略：第 1 副本放在客户端所在节点（或随机）；第 2 副本放在不同机架的节点；第 3 副本放在与第 2 副本同机架的另一节点。 设计权衡：① 容灾——任意单机架故障都不会丢数据（第 2 副本已跨机架）；② 写带宽——跨机架传输只发生 1 次（第1→第2），第2→第3 在同机架内，把写放大压到最低。若三副本全放不同机架，每次写都要 2 次跨机架传输，客户端/网络出口压力大。 前提：必须正确配置…","fu":["机架感知怎么配置？没配会怎样？","副本因子设为 1 或 5 分别在什么场景合理？"],"tag":"通用/腾讯"},{"q":"Secondary NameNode 是 NameNode 的热备吗？fsimage 和 edits 分别是什么，checkpoint 做什么？","a":"不是热备，这是最高频误区。Secondary NameNode 只负责 checkpoint：周期性把『旧 fsimage + 新 edits』合并成新 fsimage，防止 edits 日志无限增长、启动重放过慢。NameNode 真正宕机时它不能接管。 - fsimage：命名空间的全量快照（持久化）。 - edits：对命名空间的增量操作日志（顺序追加，写快）。 - checkpoint：计…","fu":["崩溃恢复时 NameNode 怎么做？","Standby NameNode 在 HA 里承担 checkpoint 角色吗？"],"tag":"通用/京东"},{"q":"HDFS 写文件的流程是怎样的？为什么用流水线（pipeline）复制？","a":"写流程：① 客户端把数据切成 packet（默认 64KB）；② 向 NameNode 申请分配目标 DataNode 列表（按副本策略）；③ 数据沿 客户端→dn1→dn2→dn3 的流水线依次推送，每个节点落盘后转发下游，ACK 沿原路回传；④ 整块写完后客户端通知 NameNode 提交，块才对读者可见（原子可见性）。 为什么流水线：客户端只发一份数据，由 DataNode 链依次转发，把客…","fu":["写入过程中某个 DataNode 挂了会怎样？","为什么正在写入的块对读者不可见？"],"tag":"通用/阿里"}]},{"id":"bd-ch02","subj":"bigdata","title":"MapReduce 原理与 YARN 调度","summary":"Map/Shuffle/Reduce 三阶段数据流；Combiner 与 Partitioner 的作用与边界；Shuffle 的排序、溢写与归并；YARN 的 ResourceManager/NodeManager/Application…","concepts":[{"id":"bd-ch02/01-mapreduce-dataflow","file":"01-mapreduce-dataflow.md","title":"Map/Shuffle/Reduce 三阶段数据流","kind":"flow","secs":[{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"def mapper(line):\n    for w in line.split():\n        yield (w.lower(), 1)\n\ndocs = [\"Hello world hello\", \"world of BigData\", \"hello bigdata world\"]\nkv = []\nfor line in docs:\n    for k, v in mapper(line):\n        kv.append((k, v))\n…"}},{"h":"二、WordCount 端到端走读","s":"（中立陈述）WordCount 是 MapReduce 的「Hello World」：Mapper 把每行 split() 成词并 (word, 1)；Partitioner 用 hash(word) % R 决定去哪个 reducer…","c":{"lang":"text","code":"input 分片 ──▶ Map(本地,并行) ──▶ [ Shuffle: 按 key 分组 ] ──▶ Reduce ──▶ 输出\n                 (k1,v1)          partition+sort       (k2, [v2..])\n                 (k1,v2)   ─────────────┐\n                 (k3,v1)   ───┐         │\n                               ▼         ▼\n                            reduce0    reduce1\n                            k1→聚合    k3→聚合\n\n  Map:  逐行转 (key, value)       例: (word,1)\n…"}}]},{"id":"bd-ch02/02-combiner-partitioner","file":"02-combiner-partitioner.md","title":"Combiner：本地 Reduce 与它的语义边界","kind":"flow","secs":[{"h":"二、Partitioner：决定 Reduce 数与数据分布","s":"（中立陈述）Partitioner 在 Map 端对每个 (key, value) 计算目标 reduce 编号 p = getPartition(key, value, R)，默认实现是 hash(key) % R。它同时决定了两件事…","c":null}]},{"id":"bd-ch02/03-shuffle-spill-merge","file":"03-shuffle-spill-merge.md","title":"Shuffle 的排序与溢写（spill）","kind":"flow","secs":[{"h":"二、归并（merge）与 Reduce 端的 fetch","s":"（中立陈述）Reduce 端通过 copy/fetch 线程 并行地从各个 MapTask 拉取属于自己的 partition 数据。数据先落「内存缓冲区」，溢满后也 spill 到本地磁盘；所有 map 数据到齐后，Reduce 端把…","c":null}]},{"id":"bd-ch02/04-yarn-arch-scheduler","file":"04-yarn-arch-scheduler.md","title":"YARN 三角色与容器分配状态机","kind":"timeline","secs":[{"h":"二、FIFO / Capacity / Fair 三种调度器","s":"（中立陈述）RM 内置三种调度器：FIFO（单队列，先到先得，大作业独占集群）、Capacity（多队列、每队列保底容量、队列内 FIFO，适合多租户保 SLA）、Fair（多队列、动态把空闲资源整合给「最饿」的作业，追求公平共享，适合…","c":null}]},{"id":"bd-ch02/05-mapreduce-tuning-recipes","file":"05-mapreduce-tuning-recipes.md","title":"bd-ch02 · MapReduce 与 YARN 调优实战：凯喵的踩坑手册","kind":"flow","secs":[{"h":"Combiner：本地先 reducer 省带宽","s":"Combiner 在 map 端本地先做一轮聚合，把 (word,1) 合并成 (word,n) 再发往 reduce，网络传输量可能降一个数量级。注意 Combiner 必须满足交换律结合律，否则结果错。","c":{"lang":"java","code":"job.setCombinerClass(WordCountReducer.class);  // 复用 reducer 逻辑做本地预聚合"}},{"h":"Partitioner 决定数据去哪","s":"默认 HashPartitioner 按 key 哈希分桶。若 key 分布不均（如按用户 id，少数大 V 数据极多），会出现数据倾斜——个别 reduce 拖死全作业。凯喵的做法：对热点 key 做加盐/二次聚合打散。","c":null},{"h":"Shuffle 的磁盘溢出与合并","s":"Map 输出先写环形缓冲，满了 spill 到磁盘，最后 merge。spill 次数过多 = 磁盘 IO 爆炸。调大 mapreduce.task.io.sort.mb、合理设 spill.percent 能减少 spill 与 me…","c":null},{"h":"YARN 的 RM / AM / NM 三角色","s":"ResourceManager 全局调度、NodeManager 管单节点资源、ApplicationMaster 是每作业一个、负责任务级调度与容错。RM 挂（未配 HA）全集群瘫痪；AM 挂 RM 会重启它。生产 RM 必须上 HA…","c":null},{"h":"Capacity vs Fair 调度差异","s":"Capacity 的 capacity 是保底占比，maximum-capacity 才是弹性上限；不设上限的队列借不到别人空闲资源。Fair 里不设 weight 才平分，设了权重按权重分，且靠 preemption 超时抢资源——不…","c":null},{"h":"小文件问题的根源","s":"HDFS 块大、元数据贵，海量小文件让 NameNode 内存爆、map 数爆炸（一个小文件一个 split 一个 map）。凯喵用 HAR、CombineFileInputFormat、或上游合并来治本。","c":null},{"h":"数据倾斜：热点 key 怎么治","s":"症状：99% reduce 早结束，剩一两个卡 99%。治法：抽样找热点 key、对热点加随机前缀打散（两阶段聚合）、或单独处理大 key。倾斜不解决，加机器也没用。","c":null},{"h":"Speculative 执行救慢任务","s":"同一任务因机器慢/磁盘忙明显落后时，YARN 启一个推测副本抢跑，先完成者胜。能掩盖偶发慢节点，但会使资源翻倍——对严重倾斜的作业可能火上浇油，必要时关掉。","c":null},{"h":"计数器与调优观测","s":"MapReduce 内置计数器（记录数、spill 次数、GC 时间）是调优的仪表盘。凯喵每次调优先看计数器：spill 多 → 调排序内存；GC 高 → 调堆；shuffle 慢 → 看网络与分区。","c":null},{"h":"作业级与集群级角色分清","s":"ApplicationMaster 是每作业一个、随作业生死；RM 才是全局唯一。别把「AM 挂了集群挂」和「RM 挂了集群挂」混为一谈——前者只丢当前作业，后者要 HA 才扛得住。","c":null},{"h":"用 Combiner 减少网络传输","s":"把 reducer 逻辑同时注册为 combiner，map 端先本地聚合，网络只传压缩后的结果。","c":{"lang":"java","code":"job.setCombinerClass(WordCountReducer.class);"}},{"h":"自定义 Partitioner 打散热点 key","s":"默认哈希分区遇到少数超大 key 会倾斜，给热点 key 加随机前缀做二次聚合。","c":{"lang":"java","code":"int p = (key.hashCode() & Integer.MAX_VALUE) % numReduce;"}},{"h":"调大排序内存减少 spill","s":"map 输出在内存里排序，内存太小会频繁 spill 到磁盘再 merge。按数据量调 io.sort.mb。","c":{"lang":"xml","code":"<property>\n  <name>mapreduce.task.io.sort.mb</name>\n  <value>512</value>\n</property>"}},{"h":"🧑‍💻 程序员视角","s":"Combiner 是「本地 reduce」，能大幅减少 shuffle 数据量，但它只能用于「满足结合律与交换律」的聚合（求和可以，求平均不行——除非传 (sum, count)）。Partitioner 决定数据去哪个 Reduce…","c":null},{"h":"🎓 博士生视角","s":"MapReduce 的性能瓶颈几乎总在 shuffle：map 输出 → 分区 → 排序 → 溢写 → 归并 → reduce 拉取，每一段都涉及磁盘与网络。优化的本质是「减少数据搬运」：Combiner 在 map 端预聚合、Part…","c":null},{"h":"📚 考研者视角","s":"大数据面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 MapReduce 中 Shuffle 阶段的描述，下列哪项正确？","stem":"下列关于 MapReduce Shuffle 的说法，哪一项是正确的？","opts":[{"k":"A","t":"Shuffle 只在 Map 阶段发生，Reduce 阶段不再涉及磁盘 IO"},{"k":"B","t":"Shuffle 横跨 Map 输出与 Reduce 输入：Map 端排序+溢写，Reduce 端 copy+归并"},{"k":"C","t":"Shuffle 是 Map 执行完毕之后才开始把数据发给 Reduce"},{"k":"D","t":"Shuffle 只对 value 排序，不对 key 排序"}],"ans":"B","why":"Shuffle 横跨两端：Map 端把 kv 写环形缓冲区、达到阈值排序并溢写(spill)、结束前归并；Reduce 端 copy 拉取、merge 归并、再喂给 reduce。它不是 Map 之后才发生，也需要磁盘 IO，且是 (partition, key) 两级排序。"},{"kind":"output","q":"给定词频，计算 Reducer 收到的输入形态","stem":"输入文本经 Mapper 后产生如下 (word,1) 中间对： (hello,1),(world,1),(hello,1),(world,1),(hello,1) 假设默认 Partitioner（hash(key)%R）保证相同 key 进同一 reducer，请问某 Reducer 处理 key=hello 时，收到的 value 迭代器内容是什么？","opts":[],"ans":"hello 对应的 value 迭代器为 [1, 1, 1]（共 3 个 1），即 (hello, [1,1,1])","why":"Reducer 的输入是 (key, Iterable<value>)，同一 key 的所有 value 被分组到一起。hello 出现 3 次，故迭代器含 3 个 1，聚合后得到 (hello, 3)。"},{"kind":"fix_error","q":"找出下列关于 Combiner 的错误说法并改正","stem":"某教材写道：「Combiner 是 Map 端的本地 Reducer，它会对所有 Map 输出的 (key, value) 先做一轮平均聚合，从而减少网络传输量，并且可以完全替代 Reducer。」请指出错误并改正。","opts":[],"ans":"该说法错误","why":"两个错误点：① 求均值不满足可结合性，直接做平均会算错；② Combiner 是优化手段而非 Reducer 的替代，跨 map 合并与最终输出仍依赖 Reducer。"},{"kind":"choice","q":"YARN 中哪个角色负责「每作业一个、向 RM 申请容器并启停 Task」？","stem":"在 YARN 架构里，提交一个 MapReduce 作业后，由哪一个组件负责：向 ResourceManager 申请资源容器、在 NodeManager 上启动/监控 Task、并向 RM 汇报作业进度？","opts":[{"k":"A","t":"ResourceManager"},{"k":"B","t":"NodeManager"},{"k":"C","t":"ApplicationMaster"},{"k":"D","t":"SecondaryNameNode"}],"ans":"C","why":"ApplicationMaster 是每作业一个的角色，负责应用级调度与容错：向 RM 申请容器、在 NM 上启停 task、盯进度。RM 做全局调度，NM 只管容器生命周期，SecondaryNameNode 属于 HDFS 而非 YARN。"},{"kind":"coding","q":"频率排序（Top K 词频聚合思想同源）","stem":"题面与完整描述请见外部链接（合规：只存元数据+链接）。本题统计字符串数组中各元素出现频率，思想与『MapReduce 中按 key 分组聚合、统计词频』同源：先分组计数，再按频率排序取前 K 个。","opts":[],"ans":"见外部链接题解","why":"分组计数本质是 map→group→reduce；可与 WordCount 的 Reducer 聚合类比理解。"},{"kind":"coding","q":"大数据倾斜下的多路归并（External Merge Sort 思想）","stem":"题面与完整描述请见外部链接（合规：只存元数据+链接）。要求把多个已排序的有序段（run）归并成一个全局有序序列，思想与『Map 端多 spill 归并、Reduce 端多路归并』同源：用最小堆做 k 路归并。","opts":[],"ans":"见外部链接题解","why":"多路归并是 Shuffle 阶段 spill 文件合成有序大文件的核心算法，也是外部排序的基石。"}],"works":[{"h":"把 Reducer 的输入当成单值 (k, v)","d":"错。Reducer 收到的输入是 (key, Iterable<value>)，即同一 key 的所有 value 组成的迭代器，形如 (word, [1,1,1])。若直接当单个 value 处理，聚合结果必然错误。正确写法：在 reduce 里遍历 values 累加/汇总；在 SQL 里理解成「GROUP BY key 后对该组…"},{"h":"认为 Combiner 一定能用、或把它当 Reducer 的替代","d":"错。Combiner 只在 Map 端本地做可结合/可交换的聚合，运行次数不确定（可能 0 次），且跨 map 的最终合并仍由 Reducer 完成。求均值、求中位数、去重计数这类不可逆/非结合的运算，直接当 Combiner 会算错（如 avg(avg,avg)≠avg）。正确写法：可结合的 sum/count/min/max 才配…"},{"h":"默认哈希分区会自动均衡、不会倾斜","d":"错。默认 hash(key) % R 是「与 key 值无关」的散列，对幂律分布（少数热 key 占绝大多数）完全无效：一个 vip_user 可能被和别的 key 哈希到同一分区，造成该 reduce 数据量爆炸、长尾卡在 99%。正确写法：识别热 key（看 counters 里某 reduce 输入远大于均值）；手写 Parti…"},{"h":"reduce 数随便设，越大越快","d":"错。mapreduce.job.reduces 既决定并行度也决定输出文件数。R 过大 → 上百个近乎空的小文件（浪费 NN 元数据、拖慢后续读、Hive 小文件问题）；R 过小 → 单 reduce 处理过多、易 OOM、慢。正确写法：按 输入量 / 256MB~1GB 估；且 reduce 数一旦定下，因为默认哈希是取模而非一致性…"},{"h":"Shuffle 是「Map 之后才发生」、只有 Map 端会落盘","d":"错。Shuffle 从 Map 写环形缓冲区就开始（排序+spill 到本地磁盘），Reduce 端也有 copy→merge→可能 spill 再归并。它是横跨 Map 输出与 Reduce 输入、且两端都涉及磁盘 IO 的过程，是作业性能的「胜负手」。正确写法：调优优先看 Shuffle：io.sort.mb 调大减少 spill…"},{"h":"Partitioner 返回的分区号可能越界或为负","d":"错。自定义 getPartition 若用 key.hashCode() % R，Java 的 % 对负哈希值会得到负数，或结果超出 [0, R)，直接抛 IOException 让 task 失败。正确写法：写成 (key.hashCode() & Integer.MAX_VALUE) % R 或 (h % R + R) % R，保…"},{"h":"AM 是常驻全局服务、和 RM 一样只有一个","d":"错。ApplicationMaster 是每作业一个、随作业生死，负责任务级调度与容错；RM 才是全局唯一。AM 挂了 RM 会重启用新容器拉起（作业不丢），但 RM 挂了（未配 HA）则全集群无法提交/调度新作业。正确写法：区分「作业级角色 AM」与「集群级角色 RM」；生产环境 RM 必须上 HA（ZKFC + ZK），否则单点。"},{"h":"Capacity 调度器的 capacity 是「上限」、Fair 调度器默认就完全公平","d":"错。capacity 是队列的保底（min-guarantee）占比，maximum-capacity 才是弹性上限；不设 maximum-capacity=100% 队列借不到别人空闲资源。Fair 里若不设 weight，各队列才平分；设了权重则按权重分，且「公平」指 max-min 公平而非绝对平分，还要靠 preemption…"}],"asks":[{"q":"MapReduce 的 Shuffle 阶段到底做了什么？为什么它既是性能瓶颈又不可避免？","a":"Shuffle 是把 Map 端产生的 (key,value) 按 key 「搬运 + 排序」到对应 Reducer 的过程，横跨两端： - Map 端：kv 先写环形缓冲区；达到 spill.percent（默认 0.8）阈值触发溢写——先按 partition、再按 key 排序（快排），写本地磁盘 spill 文件；Map 结束前把所有 spill 多路归并成有序大文件，并写 index 供…","fu":["Map 端排序用什么算法？为什么先按 partition 再按 key？","环形缓冲区大小怎么调？spill 次数过多说明什么？"],"tag":"通用/阿里"},{"q":"数据倾斜怎么识别、怎么解决？Combiner、加盐、自定义 Partitioner、MapJoin 分别在什么场景用？","a":"识别：作业监控里少数 reduce 长尾卡在 99%、其余早已完成；counters 里某 reducer 输入记录数远超均值；或某 key（如 vip_user、空值、某省份）出现频率呈幂律。 手段与边界： 1. Combiner：可结合运算（sum/count/min/max）先在 Map 端本地聚合，直接削减 shuffle 量——零成本，首选，但只缓解、不解决单 key 超大（因为同一个热…","fu":["空值导致的倾斜怎么处理？","加盐后怎么保证最终聚合结果正确？"],"tag":"通用/腾讯"},{"q":"YARN 的资源调度：FIFO / Capacity / Fair 三种调度器有什么区别？生产怎么选？","a":"三者是「吞吐量 vs 公平性 vs 隔离性」的不同取舍： - FIFO：单队列、先到先得，大作业独占集群，小作业会被堵死。只适合单机/单团队纯批处理。 - Capacity：多队列、每队列保底容量（capacity） + 弹性上限（maximum-capacity），队列内 FIFO。保证多租户 SLA、互不影响，适合「生产队列保底、实验队列借用空闲」。默认调度器即它。 - Fair：多队列、动态…","fu":["Capacity 的 capacity 是上限还是保底？maximum-capacity 不配会怎样？","Fair 的抢占（preemption）有什么代价？"],"tag":"通用/百度"}]},{"id":"bd-ch03","subj":"bigdata","title":"Hive：数据仓库与 HQL","summary":"Hive 的本质（把 SQL 翻译成 MR/Tez/Spark 作业）；内部表 vs 外部表与数据生命周期；分区与分桶、分区裁剪；JOIN 的 MapJoin 与倾斜处理；HQL 与标准 SQL 的差异（行列转换、窗口函数、Lateral…","concepts":[{"id":"bd-ch03/01-tables-internal-external","file":"01-tables-internal-external.md","title":"内部表（MANAGED）vs 外部表（EXTERNAL）","kind":"timeline","secs":[{"h":"可运行代码：把上面的说法跑一遍","s":"下面两段直接取自本章示例库（examples/），期望输出就是判题台里判定的那串字符串，不是事后补写的说明。读完正文后先照着跑一遍，再回去看「三视角解析」里对应的那条。","c":{"lang":"python","code":"# 模拟 Hive Metastore + HDFS，演示内部表 / 外部表 DROP 的差异\nmetastore = {}   # table_name -> dict(type, location)\nhdfs = {}        # location -> set of file names\n\ndef create_table(name, table_type, location, files):\n    metastore[name] = {\"type\": table_type, \"location\": location}\n    hdfs[location] = set(files)\n    print(f\"CREATE {table_type} TABLE {name} LOCATION '{location}'\")\n    for f in files:\n…"}},{"h":"二、表的生命周期与 LOCATION / EXTERNAL 工程约定","s":"（中立陈述）建表语句中 LOCATION 指定数据在 HDFS 的绝对路径；不指定时内部表落在 hive.metastore.warehouse.dir（默认 /user/hive/warehouse）。EXTERNAL 关键字让表与数…","c":null}]},{"id":"bd-ch03/02-partition-bucket","file":"02-partition-bucket.md","title":"分区表（Partition）：目录级裁剪","kind":"flow","secs":[{"h":"二、分桶表（Bucket）：文件级哈希切分","s":"（中立陈述）分桶用 CLUSTERED BY(col) INTO N BUCKETS，按 hash(bucket_col) % N 把数据散列到 N 个文件（000000_0 ... 00000N-1）。它和分区正交：分区是「目录」，分…","c":{"lang":"text","code":"Partition：目录级裁剪\n    /table/dt=2026-11-01/hour=09/part-00000\n    where dt='2026-11-01' -> 只扫该目录（分区裁剪）\n    -> 分区字段不能是高基数字段（否则海量小文件）\n\nBucket：文件内哈希分桶\n    CLUSTERED BY (user_id) INTO 16 BUCKETS\n    bucket = hash(user_id) % 16\n    用途：TABLESAMPLE 抽样、map-side join（同桶可直接对齐）\n…"}},{"h":"可运行代码：用 EXPLAIN 验证裁剪是否生效","s":"分区裁剪不能靠「我写了 WHERE 所以肯定裁了」来判断，EXPLAIN 会直接列出实际扫描的分区数：","c":{"lang":"sql","code":"-- 分区表：dt 是目录级虚拟列，不物理存在于行内\nCREATE TABLE emp_part (\n  id     BIGINT,\n  name   STRING,\n  salary DOUBLE\n)\nPARTITIONED BY (dt STRING)\nSTORED AS ORC;\n\n…"}}]},{"id":"bd-ch03/03-hql-compile-execution","file":"03-hql-compile-execution.md","title":"HQL 的编译：AST → 逻辑计划 → 物理计划","kind":"compare","secs":[{"h":"二、执行引擎与 JOIN 策略选择（MapJoin vs CommonJoin）","s":"（中立陈述）Hive 早期只把 SQL 翻成 MapReduce；现支持 Tez / Spark。JOIN 是核心算：当一张表足够小（默认 ≤ 约 25MB，由 hive.mapjoin.smalltable.filesize 控制）时…","c":null}]},{"id":"bd-ch03/04-skew-columnar","file":"04-skew-columnar.md","title":"数据倾斜与加盐两阶段聚合","kind":"stack","secs":[{"h":"二、ORC/Parquet 列式存储与谓词下推","s":"（中立陈述）ORC 与 Parquet 是 Hadoop 生态主流列式存储：数据按列连续存放（而非按行），每列块带 min/max/布隆等统计与编码（RLE、字典）。两大提速机制：列裁剪（只物化 SELECT 需要的列，跳过无关列字节）…","c":null}]},{"id":"bd-ch03/05-hive-practical-recipes","file":"05-hive-practical-recipes.md","title":"§5 bd-ch03 实战手记：凯喵带你把 Hive 用「慢」","kind":"flow","secs":[{"h":"现场一：大表 Join 小表，不写 MapJoin 就 shuffle 到死","s":"凯喵的报表任务把 10 亿行的订单表 JOIN 一个 100 行的维度表，默认走了 CommonJoin，全量 shuffle 跑 40 分钟。解法：小表（默认 ≤ 25MB，hive.auto.convert.join=true）会被…","c":{"lang":"sql","code":"-- ✅ 小表广播，map 端完成 join，无 shuffle\nSELECT /*+ MAPJOIN(d) */ o.id, d.name\nFROM orders o JOIN dim_shop d ON o.shop_id = d.id;"}},{"h":"现场二：数据倾斜靠加 Reduce 数，热 key 仍在同一个桶","s":"凯喵第一反应是「加大 mapred.reduce.tasks」，结果 99% 的任务几秒跑完，1 个卡了半小时。倾斜是「少数 key 数据量碾压」，加 Reduce 只改变取模基数，热 key 仍压到同一 Reduce（长尾）。先定位热…","c":{"lang":"sql","code":"-- 定位倾斜 key\nSELECT shop_id, COUNT(*) c FROM orders GROUP BY shop_id ORDER BY c DESC LIMIT 10;\n-- 热 key（如 NULL 或某爆款）单独处理"}},{"h":"现场三：加盐（salting）+ 两阶段聚合消倾斜","s":"凯喵的 GROUP BY 被一个 NULL key 拖垮，于是给 NULL 打随机前缀分散到多个 Reduce，聚合两次（先带盐聚合，再去盐汇总）。空值导致的倾斜先 nvl 打散或单独处理，避免全压在一个 Reduce。","c":{"lang":"sql","code":"-- 第一阶段：给热 key 加随机盐，分散到多个 reduce\nSELECT concat(nvl(shop_id,'rand'), '_', floor(rand()*10)) AS k, sum(amount) s\nFROM orders GROUP BY concat(nvl(shop_id,'rand'), '_', floor(rand()*10));\n-- 第二阶段：去盐再聚合"}},{"h":"现场四：SELECT 让列式存储优势归零","s":"凯喵的 ORC 表查 SELECT 比预期慢好几倍。ORC/Parquet 的收益来自列裁剪（只物化 SELECT 的列）和谓词下推（过滤下推到 Scan 层）。SELECT 把全部列都读出来，列存等于白上。只 SELECT 需要的列。","c":{"lang":"sql","code":"-- ❌ 读全部列，列存优势归零\nSELECT * FROM user_behavior;\n-- ✅ 只取需要的列 + 能下推的过滤列\nSELECT user_id, event_type FROM user_behavior\nWHERE dt = '2026-11-01' AND event_type = 'pay';"}},{"h":"现场五：动态分区不设 nonstrict，全表被重写到任意分区","s":"凯喵把分区值来自 SELECT 末尾列的动态分区任务一跑，瞬间生成几万个分区，NameNode 被打垮。默认 strict 要求至少一个静态分区防误写；确需全动态必须显式 nonstrict 并限制 max.dynamic.partit…","c":{"lang":"sql","code":"SET hive.exec.dynamic.partition = true;\nSET hive.exec.dynamic.partition.mode = nonstrict;   -- 风险操作，需显式开\nSET hive.exec.max.dynamic.partitions = 1000;        -- 兜底上限\nINSERT OVERWRITE TABLE logs PARTITION (dt)\nSELECT col1, col2, dt FROM staging;"}},{"h":"现场六：窗口函数不是 GROUP BY，行数不变","s":"凯喵新人写「每组 Top-N」用 GROUP BY，结果每组只剩一行，丢了明细。窗口函数（含 OVER (PARTITION BY ... ORDER BY ...)）不缩减行数，在原行上附加聚合/排名。要每组 Top-N 用 ROW_…","c":{"lang":"sql","code":"-- ✅ 每组 Top-N，明细保留\nSELECT * FROM (\n  SELECT *, ROW_NUMBER() OVER (PARTITION BY shop_id ORDER BY amount DESC) rn\n  FROM orders\n) t WHERE rn <= 3;"}},{"h":"现场七：分区裁剪看 dt 用对，否则全分区扫描","s":"凯喵的查询 WHERE dt = '2026-11-01' 秒回，改成 WHERE substr(dt,1,7)='2026-11' 就扫全表。因为对分区列做函数包裹，优化器无法做分区裁剪，只能逐个分区打开看。分区列要原样比较，别套函数…","c":{"lang":"sql","code":"-- ✅ 分区裁剪生效，只扫一个分区\nSELECT COUNT(*) FROM logs WHERE dt = '2026-11-01';\n-- ❌ 分区列被函数包裹，裁剪失效，全扫\nSELECT COUNT(*) FROM logs WHERE substr(dt,1,10) = '2026-11-01';"}},{"h":"现场八：小文件过多，Map 数爆炸还拖垮 NN","s":"凯喵的表每天 INSERT 几十次，攒出几万个小文件，读的时候起几万个 Map，NameNode 元数据爆炸。治理：① 合并小文件 hive.merge.smallfiles.avgsize；② 用 ORC + 合理桶数；③ 写时控制…","c":{"lang":"sql","code":"SET hive.merge.mapfiles = true;\nSET hive.merge.smallfiles.avgsize = 128000000;  -- 小于 128M 触发合并"}},{"h":"现场九：分桶表 JOIN 才能用 SMB Join 提速","s":"凯喵想让两个大表 JOIN 快一点，发现分桶后 JOIN 明显加速。原理：两表按相同 key 分相同数量的桶，Hive 可做 Sort-Merge-Bucket Join，每个桶内部已排序，避免一个大表全 shuffle。前提是两边桶数…","c":{"lang":"sql","code":"CREATE TABLE a (...) CLUSTERED BY (user_id) INTO 32 BUCKETS;\nCREATE TABLE b (...) CLUSTERED BY (user_id) INTO 32 BUCKETS;\n-- 同 key 同桶数 -> SMB Join 生效"}},{"h":"现场十：外部表 DROP 不删数据，误删保护靠它","s":"凯喵的同事 DROP TABLE 把对接 Kafka 落盘的表删了，数据也没了。区别：MANAGED（内部表）DROP 时元数据和数据一起删；EXTERNAL（外部表）DROP 只删元数据、数据留在 HDFS。对接外部系统、防误删的数据…","c":{"lang":"sql","code":"CREATE EXTERNAL TABLE raw_logs (...) LOCATION '/data/logs/';  -- ❌ 删表不删数据\nDROP TABLE raw_logs;  -- 元数据没了，HDFS 文件还在"}},{"h":"现场十一：LATERAL VIEW explode 行列转换先想基数","s":"凯喵用 explode 把数组炸开做标签统计，结果一行变几千行，下游聚合爆内存。explode 是行展开（一行数组 → 多行），会放大数据量。炸之前先过滤、先 size 评估基数，超大数组考虑先 LIMIT 采样。","c":{"lang":"sql","code":"SELECT tag, COUNT(*) FROM user_tags\nLATERAL VIEW explode(tags) t AS tag\nGROUP BY tag;"}},{"h":"现场十二：HQL 转 MR 的 GROUP BY 有 Combiner，但 DISTINCT…","s":"凯喵写 COUNT(DISTINCT user_id) 比 COUNT(user_id) 慢很多。因为普通 GROUP BY 在 Map 端有 Combiner 预聚合，而 DISTINCT 难以在 map 端去重（跨行），常需一次额外…","c":{"lang":"sql","code":"-- ❌ 大基数精确去重，单独 shuffle\nSELECT COUNT(DISTINCT user_id) FROM pv;\n-- ✅ 先去重再计数，减少上层数据量\nSELECT COUNT(*) FROM (SELECT DISTINCT user_id FROM pv) t;"}},{"h":"🧑‍💻 程序员视角","s":"大表 Join 小表不写 MapJoin，会走 CommonJoin 触发全量 shuffle——小表几 MB 却要搬几十 GB 的大表，慢十倍。数据倾斜靠「加 Reduce 数」是无效的：热 key 还是落在一个 Reduce 上，必…","c":null},{"h":"🎓 博士生视角","s":"Hive 的本质是「把 SQL 编译成 MapReduce/Tez/Spark 作业」，因此 SQL 的写法直接决定物理计划。列式存储（ORC/Parquet）的优势来自「按列读取 + 谓词下推 + 更高的压缩率」，这要求查询只触及必要…","c":null},{"h":"📚 考研者视角","s":"大数据面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 Hive 内部表与外部表 DROP 行为的描述，下列哪项正确？","stem":"在 Hive 中，下列关于内部表（MANAGED）与外部表（EXTERNAL）DROP TABLE 行为的说法，哪一项正确？","opts":[{"k":"A","t":"两者 DROP 时都会同时删除元数据与 HDFS 数据"},{"k":"B","t":"内部表 DROP 删除元数据+数据；外部表 DROP 只删元数据、保留 HDFS 数据"},{"k":"C","t":"两者 DROP 都只删除元数据，数据需手动清理"},{"k":"D","t":"外部表 DROP 删除数据比内部表更彻底"}],"ans":"B","why":"内部表由 Hive 全托管，DROP 同时删元数据与数据；外部表仅由 Hive 记录元数据，DROP 只删元数据、保留 HDFS 数据。二者查询/写入语法一致，区别只在生命周期。外部表常用于对接外部系统、防止误删数据。"},{"kind":"output","q":"判断下列查询能否触发分区裁剪","stem":"表 emp 按天分区（PARTITIONED BY (dt STRING)），目录下有 dt=2024-01-01、dt=2024-01-02、dt=2024-01-03 三个分区。下列两条查询，哪条会触发分区裁剪（只扫描命中目录）？ sql -- Q1 SELECT FROM emp WHERE dt = '2024-01-02'; -- Q2 SELECT FROM emp;","opts":[],"ans":"Q1 会触发分区裁剪，仅扫描 dt=2024-01-02 一个目录；Q2 无分区过滤条件，扫描全部 3 个分区目录（全表扫描），不会裁剪。","why":"分区列是目录名而非行内字段，只有对分区列做等值/范围过滤才能定位目录、跳过无关分区。Q2 不带任何过滤，必然全分区扫描。"},{"kind":"fix_error","q":"找出下列关于分桶的错误说法并改正","stem":"某笔记写道：「分桶表和分区表是一回事，都是把数据切分；把分桶数从 4 改成 8 后，Hive 会自动把数据重新均匀分布到 8 个桶，查询会更均衡。」请指出错误并改正。","opts":[],"ans":"该说法错误","why":"两个错误点：混淆分区与分桶的层级与作用；误以为改桶数会自动重分布（取模哈希无平滑扩缩容）。分桶 JOIN 提速的前提是“同列+同桶数”。"},{"kind":"choice","q":"Hive 在什么条件下会选择 MapJoin 而非 CommonJoin？","stem":"在 Hive 执行一条两表 JOIN 时，优化器在什么情况下会选择 MapJoin（广播小表）而不是 Reduce 端的 CommonJoin（Shuffle Join）？","opts":[{"k":"A","t":"只要两表都很大，就选 MapJoin 以避免 shuffle"},{"k":"B","t":"其中一张表足够小（默认 ≤ 约25MB）能放进 Map 端内存时，自动选 MapJoin"},{"k":"C","t":"MapJoin 永远比 CommonJoin 快，Hive 总是优先选它"},{"k":"D","t":"只有显式写 DISTINCT 时才会触发 MapJoin"}],"ans":"B","why":"当一张表足够小（默认 ≤ 约25MB，由 hive.mapjoin.smalltable.filesize 控制）时，优化器把小表广播到各 Map 任务、大表在 Map 端直接关联，彻底消除 Shuffle。小表超限会 OOM 或退回 CommonJoin；MapJoin 并非永远最优。"},{"kind":"coding","q":"前 K 个高频元素（词频聚合思想同源）","stem":"题面与完整描述请见外部链接（合规：只存元数据+链接）。本题统计数组中出现频率最高的前 K 个元素，思想与「Hive 中按 key 分组聚合、统计词频 / 数据倾斜前的分组计数」同源：先分组计数，再按频率排序取前 K。","opts":[],"ans":"见外部链接题解","why":"分组计数本质是 map→group→reduce；可与 Hive GROUP BY 的 Reducer 聚合、以及倾斜场景的「先局部聚合再合并」类比理解。"},{"kind":"coding","q":"大数据倾斜下的两阶段聚合（加盐思想）","stem":"题面与完整描述请见外部链接（合规：只存元数据+链接）。要求对存在极端热 key 的海量数据做分组求和：先给热 key 加随机/枚举后缀打散到多路做局部聚合（阶段一），再去掉后缀按原 key 合并（阶段二），思想与「Hive 数据倾斜的加盐 + 两阶段聚合」完全一致。","opts":[],"ans":"见外部链接题解","why":"加盐要求聚合函数可结合/可交换（sum/count/min/max）；两阶段结果与直接聚合一致，但把单 Reduce 长尾负载均摊到多路，是处理数据倾斜的通用手法。"}],"works":[{"h":"把内部表当外部表用，DROP 把数据一起删了","d":"错。内部表（MANAGED）DROP TABLE 会同时删除元数据与 HDFS 数据；外部表（EXTERNAL）只删元数据、保留数据。正确写法：对接外部系统（Flume/Kafka 落盘、其他引擎共用）的表一律建 EXTERNAL；需要 Hive 全托管的临时/中间表才用内部表。误删内部表数据不可恢复（除非有快照/回收站）。"},{"h":"把分区字段当普通列，导致全表扫描、分区裁剪失效","d":"错。分区列是目录层级（/dt=2024-01-02/），不是行内字段；只有 WHERE dt='...' 这类等值/范围过滤分区列才能触发 partition pruning，直接跳过无关目录。正确写法：查询务必带上分区过滤条件；避免在分区列上做函数变换（如 substr(dt,1,7)='2024-01'）否则裁剪失效；分区粒度别过…"},{"h":"分桶数随便设、或把分桶当分区用","d":"错。分桶按 hash(bucket_col) % N 决定文件（/000000_0 ...），用于 JOIN 避免 shuffle、采样、SORTED BY；分区是目录级裁剪。二者正交：分区管「扫哪些目录」，分桶管「目录内如何切文件」。正确写法：分桶数取 2 的幂、与 Reduce 数对齐；只有两表按同一列、同一桶数分桶的 JOIN…"},{"h":"认为 MapJoin 永远最优、小表一定能广播","d":"错。MapJoin 仅当小表能放进各 Map 任务内存（hive.auto.convert.join 默认阈值约 25MB，由 hive.mapjoin.smalltable.filesize 控制）才安全；小表过大广播会 OOM、或退化为 CommonJoin。正确写法：确认小表真实大小再开 MapJoin；维度表膨胀后改用分桶 J…"},{"h":"动态分区不设 nonstrict，整张表被误写/作业失败","d":"错。动态分区让分区值来自 SELECT 末尾列，可能瞬间生成海量分区；默认 hive.exec.dynamic.partition.mode=strict 要求至少一个静态分区，防误把全表重写到任意分区。正确写法：确需全动态时显式设 nonstrict 并限制 hive.exec.max.dynamic.partitions，否则一个…"},{"h":"数据倾斜靠「加大 Reduce 数」解决","d":"错。倾斜是「某一/少数 key 数据量碾压其余」，加 Reduce 数只改变取模基数、把热 key 仍压到同一个 Reduce（长尾卡 99%）。正确写法：先用 counters/监控定位热 key；小表侧用 MapJoin 消 shuffle；大表自身热 key 用加盐（salting）+ 两阶段聚合或自定义 Partitioner…"},{"h":"以为列式存储「自动」就快，不写谓词下推/列裁剪","d":"错。ORC/Parquet 的收益来自列裁剪（只物化 SELECT 的列）与谓词下推（过滤下推到 Scan 层，尽量少读、尽早过滤）。若 SELECT 或过滤列不在存储统计里，列存优势大打折扣。正确写法：只 SELECT 需要的列；把过滤条件写在能下推的列上（分区列、排序列、有 min/max 统计的列）；避免对列做函数包裹破坏下推。"},{"h":"窗口函数和 GROUP BY 混为一谈","d":"错。GROUP BY 缩减行数（每组聚成一行）；窗口函数（含 OVER (PARTITION BY ... ORDER BY ...)）不缩减行数，在原行上附加聚合/排名结果。正确写法：要「每组 Top-N」用 ROW_NUMBER() ... WHERE rn<=N；要「每组聚合后拼回明细」用窗口聚合而非 GROUP BY；注意窗口…"}],"asks":[{"q":"Hive 内部表和外部表的区别是什么？生产上怎么选型？DROP 一张大表前你要确认什么？","a":"区别：内部表（MANAGED）由 Hive 全托管，DROP 同时删元数据 + HDFS 数据；外部表（EXTERNAL）只由 Hive 记录元数据，DROP 只删元数据、保留数据。二者查/写 SQL 完全一致，区别只在生命周期。 选型：数据不是 Hive 独占的（Flume/Kafka 落盘、Spark 产出、多引擎共用）——一律外部表；纯 Hive 内部加工链路的临时/中间表——用内部表（删表…","fu":["外部表被 DROP 后数据还在，怎么重新挂回 Hive？","Hive Metastore 在多引擎共用数据时扮演什么角色？"],"tag":"通用/阿里"},{"q":"一条 HQL 在 Hive 里是怎么变成分布式作业的？逻辑计划和物理计划有什么区别？","a":"经历五步：① 语法分析（Antlr） 生成 AST；② 语义分析 绑定元数据、类型检查，生成逻辑计划（关系代数树：TableScan/Filter/Aggregate/Project，与引擎无关）；③ 逻辑优化（谓词下推、列裁剪、常量折叠、CBO 代价重排 join 顺序）；④ 翻译成物理计划（具体算子 + 执行引擎：Map→Shuffle→Reduce，或 Tez DAG / Spark RDD…","fu":["谓词下推和列裁剪分别发生在哪个阶段？为什么能提速？","CBO 是基于什么统计信息估算代价的？"],"tag":"通用/字节"},{"q":"数据倾斜怎么识别和解决？MapJoin、加盐、自定义 Partitioner 分别适合什么场景？","a":"识别：少数 Reduce 长尾卡 99%、其余早已完成；counters 里某 Reduce 输入远超均值；某 key（热用户/空值/某省份）呈幂律。先 EXPLAIN+counters 定位热 key，别盲调。 手段与边界： 1. MapJoin：倾斜来自「大表 JOIN 小维度表」时最优——小表广播、彻底消 shuffle，前提是小表能进内存。 2. 加盐 + 两阶段聚合：大表自身热 key（…","fu":["为什么「加大 Reduce 数」解决不了倾斜？","加盐后怎么保证最终结果和直接聚合一致？"],"tag":"通用/腾讯"},{"q":"分区和分桶的区别？ORC/Parquet 为什么比 TextFile 快？列裁剪和谓词下推是什么？","a":"分区 vs 分桶：分区是目录级（按列值切目录、用于扫描裁剪），分桶是文件级（hash(col)%N 切文件、用于 JOIN 免 shuffle 与采样），二者正交可叠加。分桶 JOIN 提速前提是「同列+同桶数」。 列存为什么快：ORC/Parquet 按列连续存储，同列类型一致、冗余高，便于 RLE/字典编码+压缩；分析查询多窄列访问，I/O 从「整行」降到「选中列」。 列裁剪：只物化 SELE…","fu":["分桶数改成 2 的幂以外的值会怎样？改桶数要全量重写吗？","ORC 的 bloom filter 在什么查询下推最有效？"],"tag":"通用/百度"}]},{"id":"bd-ch04","subj":"bigdata","title":"Spark 核心：RDD 与惰性求值","summary":"为什么比 MapReduce 快（内存计算 + DAG 优化）；RDD 的五个属性与不可变性；Transformation 与 Action 的惰性求值；宽依赖与窄依赖、Stage 与 Task 的划分；缓存（cache/persist）级…","concepts":[{"id":"bd-ch04/01-rdd-and-lineage","file":"01-rdd-and-lineage.md","title":"RDD 的本质与五大特性","kind":"flow","secs":[{"h":"二、不可变性与血缘（lineage）容错","s":"（中立陈述）每个 RDD 只记录「我是怎么由父 RDD 算出来的」（依赖 + 算子），这个谱系称为 lineage / DAG。因为 RDD 不可变，lineage 是一条单向、无环、可重放的因果链：出错时沿链回溯即可精确重算丢失的分区…","c":{"lang":"text","code":"血缘 DAG（自下而上，缩进=父级依赖）:\n        RDD#1 [parallelize 分区=4]\n      RDD#2 [map x=>x*2]\n    RDD#3 [filter x%2==0]\n  RDD#4 [reduceByKey 宽依赖]\nRDD#5 [collect Action]\n血缘节点总数 = 5\n构建 5 个 RDD 谱系，但全程未触发一次数据计算（惰性）"}}]},{"id":"bd-ch04/02-lazy-evaluation-dag","file":"02-lazy-evaluation-dag.md","title":"惰性求值（Lazy Evaluation）语义","kind":"flow","secs":[{"h":"二、Transformation 与 Action 的判别","s":"（中立陈述）Transformation 接收 RDD、返回新 RDD，是惰性的（如 map、filter、flatMap、groupByKey、reduceByKey、join、union、distinct、sortBy、persis…","c":{"lang":"text","code":"Transformation 惰性, 返回新 RDD:\n  - map\n  - filter\n  - flatMap\n  - groupByKey\n  - reduceByKey\n  - join\n  - union\n  - distinct\n…"}}]},{"id":"bd-ch04/03-dependency-stage-task","file":"03-dependency-stage-task.md","title":"窄依赖 vs 宽依赖（依赖模型）","kind":"compare","secs":[{"h":"二、Stage 划分与 Task 数量计算","s":"（中立陈述）Spark 以 宽依赖（及最终的 action）为边界 把 DAG 切成一个个 Stage：一个 Stage 内的所有算子都是窄依赖，可流水线执行；遇到宽依赖就切断，前后分属不同 Stage（宽依赖两端各形成一个 Shuff…","c":{"lang":"text","code":"Stage 划分（每个宽依赖/Action 切断一次）:\n  Stage1: ['A', 'B', 'C']\n  Stage2: ['D', 'E']\nStage 数 = 2\n每个 Stage 内 Task 数 = 分区数 = 4; 总 Task 数 = 8"}}]},{"id":"bd-ch04/04-cache-shuffle-tuning","file":"04-cache-shuffle-tuning.md","title":"缓存（cache/persist）与 checkpoint 的取舍","kind":"compare","secs":[{"h":"二、算子选择与数据倾斜（工程调优三板斧）","s":"（中立陈述）同一语义可用不同算子实现，Shuffle 代价天差地别：reduceByKey 在 map 端先做本地预聚合，只把「key→局部聚合值」搬过网络；groupByKey 把全量记录原样搬过网络再聚合，Shuffle 量远大于前…","c":{"lang":"text","code":"记录总数 = 12, 不同 key 数 = 6\ngroupByKey 全量搬运: shuffle 记录数 = 12\nreduceByKey map端预聚合后搬运: shuffle 记录数 = 6\nreduceByKey 减少 shuffle 量 = 6 条 (约 50%)"}}]},{"id":"bd-ch04/05-spark-practical-recipes","file":"05-spark-practical-recipes.md","title":"Spark 实战手记：凯喵的十二次「跑了一夜还在 Shuffle」复盘","kind":"flow","secs":[{"h":"开场：为什么 Spark 比 MapReduce 快，又为什么有时候更慢","s":"教科书答案是「内存计算」。凯喵第一次听到这话时以为 Spark 不落盘，后来发现 Shuffle 阶段照样落盘，而且落得比 MapReduce 还猛。","c":{"lang":"scala","code":"// 从并行集合创建：分区数和优先位置都由本地决定\nval rdd = sc.parallelize(1 to 1000, numSlices = 8)\n\n// 从 HDFS 创建：优先位置来自文件块所在节点\nval logs = sc.textFile(\"hdfs:///logs/2026-11-01/*.log\")\n\n// 关键：分区数决定了后续 task 的并行度\nprintln(logs.getNumPartitions)"}},{"h":"收尾：Spark 调优就是守住那三条前提","s":"凯喵最后总结：Spark 快的三条前提——窄依赖融合、惰性求值看见全貌、缓存避免重算——对应三类调优动作：","c":null}]}],"exams":[{"kind":"choice","q":"下列关于 RDD 五大特性的描述，正确的是？","stem":"Spark 官方给出的 RDD 五大特性包括：一组分区列表、对每个分区的计算函数、对其他 RDD 的依赖列表、（键值 RDD 的）分区器、（每个分区的）首选位置。下列说法正确的是？","opts":[{"k":"A","t":"RDD 是可变数据集，transformation 会原地修改它"},{"k":"B","t":"RDD 不可变，transformation 返回新 RDD；容错靠 lineage 重算而非副本"},{"k":"C","t":"RDD 默认在内存中保留所有数据副本以实现容错"},{"k":"D","t":"分区器是所有 RDD 都必须具备的特性"}],"ans":"B","why":"RDD 不可变，任何 transformation 返回新 RDD；容错依靠 lineage（依赖链）重算丢失分区，而不是数据副本（对比 HDFS）。分区器仅键值型 Shuffle RDD 有，非必选。"},{"kind":"output","q":"判断下列算子哪些是 transformation、哪些是 action","stem":"下列算子中，哪些是 transformation（惰性、返回 RDD），哪些是 action（触发计算、不返回 RDD）？ - map - reduceByKey - collect - count - filter - saveAsTextFile","opts":[],"ans":"transformation：map、reduceByKey、filter（返回新 RDD，惰性，不触发计算）。action：collect、count、saveAsTextFile（触发实际计算，不返回 RDD）。判别法：返回值是否为 RDD。","why":"transformation 类型为 RDD→RDD 且惰性；action 触发计算并返回标量/集合/写外部。reduce 是 action，reduceByKey 是 transformation，二者易混。"},{"kind":"fix_error","q":"找出下列关于依赖模型的错误说法并改正","stem":"某笔记写道：「map、filter、reduceByKey、groupByKey 都是窄依赖，因为它们都只是对数据做变换；宽依赖只发生在 join 的时候。reduceByKey 和 groupByKey 区别不大，随便用。」请指出错误并改正。","opts":[],"ans":"该说法错误","why":"宽依赖的本质是「子分区依赖父全部分区」。聚合类算子几乎都是宽依赖；reduceByKey 的相对优势在于 map 端 combiner。"},{"kind":"choice","q":"一段 RDD 程序的 Stage 数与总 Task 数","stem":"设 RDD 分区数 = 4。程序为：sc.parallelize(...).map(...).filter(...).reduceByKey(...).map(...).collect()。请问该 job 的 Stage 数与总 Task 数分别是？","opts":[{"k":"A","t":"Stage=1，Task=4"},{"k":"B","t":"Stage=2，Task=8"},{"k":"C","t":"Stage=2，Task=4"},{"k":"D","t":"Stage=3，Task=12"}],"ans":"B","why":"reduceByKey 是宽依赖，把 DAG 切成 2 个 Stage（窄依赖链 map→filter 为一个，reduceByKey→map 为另一个）。每个 Stage 的 Task 数 = 末态分区数 = 4，总 Task = 4+4 = 8。"},{"kind":"choice","q":"cache 与 checkpoint 的区别","stem":"关于 cache()/persist() 与 checkpoint() 的区别，下列描述正确的是？","opts":[{"k":"A","t":"两者都会截断 lineage，故障后都从可靠存储恢复"},{"k":"B","t":"cache 保留 lineage、缓存丢失靠重算；checkpoint 斩断 lineage、从可靠存储恢复"},{"k":"C","t":"checkpoint 比 cache 更快，应优先用 checkpoint"},{"k":"D","t":"cache 后任何 executor 失效都不会触发重算"}],"ans":"B","why":"cache/persist 物化结果但保留 lineage，缓存丢失（executor 失效/被挤出）仍沿 lineage 重算；checkpoint 写入可靠存储并置空父指针，斩断 lineage，恢复从文件读。checkpoint 有额外写入代价，故常在之前先 cache。"},{"kind":"coding","q":"用 Python 从零模拟 reduceByKey（map 端预聚合 + 合并）","stem":"不使用任何 Spark API，用纯 Python 实现一个极简 reduceByKey：先按 key 做 map 端本地聚合（预聚合），再把各分区的局部结果按 key 合并（combine），最终得到全局聚合结果。验证 ('a',2),('b',1),('a',3) 得到 {'a':5,'b':1}。","opts":[],"ans":"def reduce_by_key(pairs): # map 端本地预聚合：每个分区内先按 key 聚成局部结果 local = {} for k, v in pairs: local[k] = local.get(k, 0) + v return local def combine(locals): # reduc…","why":"reduceByKey 的两段式（map 端预聚合 + reduce 端合并）正是它比 groupByKey 省 Shuffle 的原因：map 端已把同 key 多条记录压成一条局部聚合。"},{"kind":"coding","q":"词频统计 Top-K（与 reduceByKey 同源）","stem":"题面与完整描述请见外部链接（合规：只存元数据+链接）。统计文本中出现频率最高的前 K 个单词，思想与「RDD 中按 key 分组聚合、词频统计」完全同源：先分组计数（map→reduceByKey），再按频率排序取前 K。","opts":[],"ans":"见外部链接题解（合规：只存元数据与链接，不搬运题面正文）","why":"词频聚合本质是 map→group→reduce；可与 RDD 的 reduceByKey、以及倾斜场景的「先局部聚合再合并」类比理解。"},{"kind":"coding","q":"大数据倾斜下的两阶段聚合（加盐思想）","stem":"题面与完整描述请见外部链接（合规：只存元数据+链接）。要求对存在极端热 key 的海量数据做分组求和：先给热 key 加随机/枚举后缀打散到多路做局部聚合（阶段一），再去掉后缀按原 key 合并（阶段二），思想与「Spark 数据倾斜的加盐 + 两阶段聚合」完全一致。","opts":[],"ans":"见外部链接题解（合规：只存元数据与链接，不搬运题面正文）","why":"加盐要求聚合函数可结合/可交换（sum/count/min/max）；两阶段结果与直接聚合一致，但把单 Reduce 长尾负载均摊到多路，是处理数据倾斜的通用手法。"}],"works":[{"h":"以为 transformation 会立即执行（忘了惰性求值）","d":"错。map/filter/reduceByKey 等 transformation 只记录操作、不触发计算，只有 collect/count/saveAsTextFile 等 action 才真正跑。正确写法：需要触发计算时显式调用 action；别在 transformation 链里期待「马上看到结果」，调试用 toDebugSt…"},{"h":"把 reduceByKey 当 groupByKey 用，导致 Shuffle 数据量爆炸","d":"错。groupByKey 把全量记录原样搬过网络再聚合；reduceByKey 先在 map 端做本地预聚合，只搬「key→局部聚合值」。正确写法：聚合优先 reduceByKey/aggregateByKey/combineByKey，map 端 combiner 能把 Shuffle 量从「总记录数」压到「不同 key 数」。"},{"h":"在超大 key 上滥用 groupByKey","d":"错。groupByKey 不仅 Shuffle 量大，还在 reduce 端把同 key 全量记录拉进内存做迭代，极易 OOM 与倾斜。正确写法：可结合/可交换的聚合一律用 reduceByKey；不可结合的（如取 Top-N）用 reduceByKey+ 本地堆或 aggregateByKey 控制每 key 内存。"},{"h":"缓存用错级别 / 物化后不释放","d":"错。cache() 默认 MEMORY_ONLY，数据放不下会频繁落盘或丢弃重算；长期不用的 RDD 不 unpersist 会一直占内存。正确写法：内存紧张用 MEMORY_AND_DISK；复用结束立即 unpersist()；只缓存「被多个 action 复用」的中间结果，而非一上来就缓存所有 RDD。"},{"h":"以为 cache 后永远不重算","d":"错。缓存只保留 lineage，executor 丢失或缓存被 LRU 挤出后，未 checkpoint 的分区仍沿 lineage 重算。正确写法：对 lineage 超长或重算代价高的 RDD 用 checkpoint() 斩断依赖；checkpoint 前先 cache() 避免重复全量计算。"},{"h":"lineage 过长不截断，Driver OOM / 重算爆炸","d":"错。成百上千个 transformation 会让 DAG 图谱与重算代价失控。正确写法：在血缘关键节点 checkpoint() 截断；迭代算法（如 PageRank、图计算）每若干轮 checkpoint 一次。"},{"h":"窄依赖 / 宽依赖判断错误，Stage 与 Task 数算错","d":"错。map/filter/union/mapPartitions/coalesce(默认) 是窄依赖；reduceByKey/groupByKey/join(非广播)/distinct/sortBy/repartition 是宽依赖（触发 Shuffle）。正确写法：Stage 以宽依赖+action 为界切分；Task 数 = 各…"},{"h":"并行度 / 分区数设太小，Task 数不足、资源浪费","d":"错。分区数直接决定每个 Stage 的 Task 数；分区远小于总核数时大量核空闲。正确写法：设 spark.default.parallelism 与 spark.sql.shuffle.partitions 为集群总核的 2~3 倍；读 HDFS 时分区≈块数的合理倍数。"}],"asks":[{"q":"Spark 为什么比 MapReduce 快？RDD 的五大特性是什么？","a":"快的三点核心：① 内存计算——中间结果默认留内存而非落 HDFS，省掉 MR 每步写盘/读盘的 I/O；② DAG 调度——把一串算子优化成一个 DAG，多个 map 阶段 pipeline 进同一个 Stage，减少落盘与任务启动；③ 惰性求值——transformation 只记录、action 才触发，Spark 能对整条计划做全局优化（算子融合、谓词下推到 Scan）。 RDD 五大特性：…","fu":["RDD 容错和 HDFS 副本容错有什么本质区别？","为什么说 lineage 重算要求 transformation 是确定性的？"],"tag":"通用/阿里"},{"q":"什么是惰性求值？Transformation 和 Action 有什么区别？","a":"惰性求值：transformation（map/filter/reduceByKey 等）只往 lineage 追加一个「要做什么」的节点、不立即执行；只有 action（collect/count/saveAsTextFile/take 等）出现才真正沿 DAG 计算。好处是 Spark 能拿到完整计划做全局优化（算子融合、合并 Stage、削减中间物化）。 判别：返回值是否为 RDD——tra…","fu":["给一段代码问「实际触发了几次计算」怎么答？","为什么反复对未缓存 RDD 调 action 会重复重算？"],"tag":"通用/字节"},{"q":"窄依赖和宽依赖的区别？哪些算子产生宽依赖？Stage 怎么划分、Task 数怎么算？","a":"窄依赖：子 RDD 每个分区只依赖父 RDD 至多一个分区（map/filter/union/mapPartitions/coalesce 默认）——可 pipeline 同 Stage、零网络。宽依赖：子分区依赖父全部分区，必然 Shuffle（reduceByKey/groupByKey/join 非广播/distinct/sortBy/repartition）。 Stage 划分：以宽依赖和…","fu":["为什么宽依赖无法和前面的窄依赖 pipeline 在一起？","Task 数和分区数、Stage 数的关系？"],"tag":"通用/腾讯"},{"q":"reduceByKey 和 groupByKey 哪个好？为什么？","a":"reduceByKey 更优，因为它在 map 端先做本地预聚合（combiner），只把「key→局部聚合值」搬过网络；groupByKey 把全量记录原样搬运到 reduce 端再聚合。Shuffle 量：reduceByKey ≈ 不同 key 数，groupByKey = 总记录数——差一个数量级，且 groupByKey 在 reduce 端把同 key 全量记录拉进内存，极易 OOM…","fu":["groupByKey 为什么容易 OOM？","什么场景 reduceByKey 不能替代 groupByKey？"],"tag":"通用/百度"}]},{"id":"bd-ch05","subj":"bigdata","title":"Spark SQL、DataFrame 与 Catalyst","summary":"DataFrame/Dataset 与 RDD 的取舍（结构化信息与优化空间）；Catalyst 优化器（逻辑计划 → 优化 → 物理计划）、谓词下推与列裁剪；Tungsten 的堆外内存与全阶段代码生成；AQE 自适应执行与动态分区合并…","concepts":[{"id":"bd-ch05/01-dataframe-dataset-rdd","file":"01-dataframe-dataset-rdd.md","title":"从 RDD 到 DataFrame：结构化信息就是优化空间","kind":"flow","secs":[{"h":"二、Dataset 的类型安全与编码器（Encoder）","s":"（中立陈述）Dataset[T] 在 DataFrame（即 Dataset[Row]）之上加了一层编译期类型：","c":{"lang":"text","code":"RDD 无 schema，只有闭包 -> 优化器无从下手\nDataFrame / Dataset 带 schema -> Catalyst 可做等价变换与代价优化\n\n    RDD        逐条 JVM 对象，GC 压力大，调用黑盒\n    DataFrame  逻辑计划 -> 优化 -> 物理计划 -> 列式批处理 + 代码生成\n\n    Catalyst 常见优化：\n      谓词下推、列裁剪、常量折叠、按大小重排 join\n      whole-stage codegen：把多个算子编译成一个循环（消除虚调用与中间对象）\n…"}}]},{"id":"bd-ch05/02-catalyst-optimizer","file":"02-catalyst-optimizer.md","title":"Catalyst 优化器：四个阶段与规则批机制","kind":"flow","secs":[{"h":"二、谓词下推、列裁剪、常量折叠与 JOIN 重排","s":"（中立陈述）逻辑优化阶段最有代表性的四条规则：","c":{"lang":"python","code":"q = (spark.read.parquet(\"s3://bucket/orders\")\n     .filter(F.col(\"dt\") == \"2026-10-01\")\n     .select(\"user_id\", \"amount\"))\n\nq.explain(\"formatted\")"}}]},{"id":"bd-ch05/03-tungsten-and-codegen","file":"03-tungsten-and-codegen.md","title":"Tungsten：堆外内存管理与紧凑二进制布局","kind":"stack","secs":[{"h":"二、全阶段代码生成（Whole-Stage Codegen）","s":"（中立陈述）传统的火山模型（Volcano Iterator Model）里，每个算子实现 next()，","c":{"lang":"text","code":"Tungsten 解决两件事：内存布局 + 代码生成\n    堆外内存自己管理 -> 绕过 JVM 对象头与 GC\n    紧凑二进制：多列拼成一条 UnsafeRow（定长偏移表 + 变长区）\n    whole-stage codegen：把 filter+project+agg 编成一个 Java 循环\n\n    效果：消除虚函数调用与中间对象，CPU 缓存友好\n\n    逻辑计划（scan/filter/agg） ──codegen──▶ 单个生成方法\n                                              for (row : rows) { ... }\n…"}}]},{"id":"bd-ch05/04-aqe-shuffle-and-metastore","file":"04-aqe-shuffle-and-metastore.md","title":"AQE 自适应执行：用运行时统计纠正编译期误判","kind":"flow","secs":[{"h":"二、宽依赖 / 窄依赖与 Shuffle 边界","s":"（中立陈述）沿用 bd-ch04 的定义：窄依赖 = 一个父分区只被子分区中的一个使用","c":null},{"h":"三、执行计划读法与 Hive Metastore 集成","s":"（中立陈述）读计划的固定顺序：① 找所有 Scan（读了哪些表、哪些列、估计多少行）；","c":{"lang":"text","code":"AQE 用运行时统计纠正编译期误判（编译期只能靠可能过期的统计信息猜）\n\n    三个自适应能力：\n      ① 动态合并 shuffle 分区（小分区合并，避免海量小 task）\n      ② 动态切换 join 策略（sort-merge -> broadcast，若一侧实际很小）\n      ③ 动态处理倾斜（把超大分区再切分）\n\n    前提：shuffle 阶段要物化统计（spark.sql.adaptive.enabled）\n\n…"}}]}],"exams":[{"kind":"choice","q":"下列关于 RDD 与 DataFrame 差异的说法，错误的是？","stem":"Spark 同时提供 RDD 与 DataFrame 两套 API。关于二者在「结构化信息与优化空间」上的差异，下列说法错误的是？","opts":[{"k":"A","t":"DataFrame 带 schema 与逻辑计划，Spark 因此能做谓词下推与列裁剪"},{"k":"B","t":"RDD 的 lambda 对 Spark 是不透明黑盒，无法做语义等价的重写"},{"k":"C","t":"DataFrame 底层不依赖 RDD，是独立实现的一套执行引擎"},{"k":"D","t":"DataFrame 使用 Tungsten 紧凑二进制表示，减少对象头与装箱开销"}],"ans":"C","why":"DataFrame 是建立在 RDD 之上的高层 API，df.rdd 可以取到底层 RDD；它并没有另起一套执行引擎，而是在 RDD 之上补了 schema 与逻辑计划两层信息，从而打开优化空间。A、B、D 均为标准表述。"},{"kind":"choice","q":"一条 SQL 在 Spark SQL 中的处理顺序是？","stem":"Catalyst 优化器把一条 SQL 变成可执行代码要经过若干阶段。正确的顺序是？另外，AnalysisException: Column 'xxx' cannot be resolved 来自哪一阶段？","opts":[{"k":"A","t":"解析 → 分析（绑定元数据）→ 逻辑优化 → 物理计划 → 代码生成；报错来自分析阶段"},{"k":"B","t":"解析 → 逻辑优化 → 分析 → 物理计划 → 代码生成；报错来自逻辑优化阶段"},{"k":"C","t":"解析 → 物理计划 → 逻辑优化 → 代码生成；报错来自物理计划阶段"},{"k":"D","t":"分析 → 解析 → 逻辑优化 → 物理计划 → 代码生成；报错来自解析阶段"}],"ans":"A","why":"顺序是：① 解析（ANTLR 生成未解析 AST）→ ② 分析（查 Catalog / Hive Metastore 绑定列名与类型，列不存在或类型不匹配就在这一步抛 AnalysisException）→ ③ 逻辑优化（规则批重写到不动点）→ ④ 物理计划（按代价选算子）→ ⑤ 代码生成。解析阶段只看语法，看不到列名是否存在。"},{"kind":"choice","q":"下列哪种情况谓词下推不会生效？","stem":"谓词下推（Predicate Pushdown）是 Catalyst 最重要的优化之一，但有明确的失效条件。下列哪种情况不会下推？","opts":[{"k":"A","t":"谓词引用的列不在下方算子的输出列中"},{"k":"B","t":"谓词是确定性表达式，且引用列可由下方算子提供"},{"k":"C","t":"谓词作用在分区列上，且为「分区列 = 常量」的直接比较"},{"k":"D","t":"谓词只引用左表的列，而它被写在 JOIN 之后"}],"ans":"A","why":"两条硬约束：① 谓词必须确定性（含 rand()、current_timestamp() 的不下推，因为下推会改变每行求值次数）；② 谓词引用的列必须在下方算子输出列内——若 Project 已经把该列投影掉，就推不下去。B/C/D 都是可以下推的典型场景（C 还能进一步触发分区裁剪）。"},{"kind":"coding","q":"实现列裁剪：给定计划需求，计算各 Scan 实际读取的列","stem":"已知查询：SELECT u.city, sum(o.amount) FROM orders o JOIN users u ON o.uid = u.uid GROUP BY u.city。 表结构：orders(id, uid, dept, amount, ts)、users(uid, city, age)。 请实现自顶向下的列裁剪：从根节点（聚合）真正需要的列出发，把需求逐层下推到 Scan，并…","opts":[],"ans":"orders 裁剪前 5 列 -> 裁剪后 2 列: ['uid', 'amount'] users 裁剪前 3 列 -> 裁剪后 2 列: ['uid', 'city'] 判据 列数下降: True","why":"列裁剪的核心是「需求自顶向下传播」：聚合只需要 city 与 amount，JOIN 额外需要 uid。于是 orders 只需 uid, amount（2 列，省掉 id, dept, ts），users 只需 uid, city（2 列，省掉 age）。注意 SELECT 会让需求集等于全属性集，裁剪立即失效。"},{"kind":"choice","q":"关于广播 JOIN 触发条件的正确表述是？","stem":"广播 JOIN（BroadcastHashJoin）能消掉一次 Shuffle，但它有明确的触发条件与陷阱。下列表述正确的是？","opts":[{"k":"A","t":"只要小表的磁盘文件大小小于 10MB 就一定广播"},{"k":"B","t":"必须是等值连接，且优化后计划的 sizeInBytes 不超过阈值，且统计信息存在"},{"k":"C","t":"非等值连接同样可以走 BroadcastHashJoin"},{"k":"D","t":"把 spark.sql.autoBroadcastJoinThreshold 调成 -1 会强制广播所有 JOIN"}],"ans":"B","why":"触发广播的三个前置条件：① 等值连接（非等值只能走 BroadcastNestedLoopJoin，代价 O(n×m)）；② 小表优化后计划的 sizeInBytes ≤ spark.sql.autoBroadcastJoinThreshold（默认 10MB）；③ 该统计存在——表没做过 ANALYZE TABLE 时 sizeInBytes 为缺省值，就不广播。A 错在 S…"},{"kind":"choice","q":"关于 AQE 与倾斜判定，下列说法正确的是？","stem":"Spark 3.2 起 AQE（Adaptive Query Execution）默认开启。关于它的三大能力与倾斜判定口径，下列说法正确的是？","opts":[{"k":"A","t":"AQE 在编译期根据统计信息合并分区，与运行时数据无关"},{"k":"B","t":"倾斜分区的判定口径是「分区大小 > 5 × 中位数 且 > 256MB」"},{"k":"C","t":"AQE 处理倾斜的手段是把倾斜分区整体丢弃以保证作业完成"},{"k":"D","t":"AQE 默认关闭，必须手动设置 spark.sql.adaptive.enabled=true"}],"ans":"B","why":"AQE 的三大能力是：动态合并 Shuffle 小分区、动态把 SortMergeJoin 切换为 BroadcastHashJoin、动态拆分倾斜分区。倾斜判定口径正是「分区大小 > skewedPartitionFactor(默认 5) × 中位数 且 > skewedPartitionThresholdInBytes(默认 256MB)」。A 错（AQE 用的是运行时真实…"},{"kind":"coding","q":"LeetCode 184：用「先聚合后连接」改写部门最高工资查询（SQL 优化视角）","stem":"本题取自 LeetCode 数据库题库（题目正文请点击链接查看，此处只存元数据与链接）。 练习要求（优化视角）：在求「每个部门工资最高的员工」这类查询时，对比两种写法的执行计划： 1. 先 JOIN 两张表再 WHERE salary = (SELECT max(...) ...)； 2. 先按部门聚合出 max(salary)，再与原表做等值 JOIN。 请用 EXPLAIN 观察两版计划中 E…","opts":[],"ans":"-- 先聚合出每个部门的最高工资，再与原表等值 JOIN WITH dept_max AS ( SELECT departmentId, MAX(salary) AS max_salary FROM Employee GROUP BY departmentId ) SELECT d.name AS Department…","why":"第 2 种写法的收益来自两点：① 聚合前置——GROUP BY departmentId 把参与 JOIN 的数据量从「员工数」压到「部门数」，Shuffle 量与 JOIN 输入都大幅下降；② 维度表广播——Department 是小表，sizeInBytes 低于阈值时 Catalyst 会选 BroadcastHashJoin，直接消掉一次 Exchange。用 EXPL…"},{"kind":"coding","q":"实现一个迷你 Catalyst：谓词下推 + 列裁剪两条规则","stem":"参考 apache/spark 的 sql/catalyst/optimizer 模块，用 Python 实现一个迷你 Catalyst 规则引擎。 给定逻辑计划（Python 字典树）： text Aggregate(group=[city], funcs=[amount]) Filter(pred=\"city='bj'\", refs=[city], det=True) Join(key=uid…","opts":[],"ans":"orders: 5 列 -> 2 列 ['uid', 'amount'] users: 3 列 -> 2 列 ['uid', 'city'] 谓词已下推到 users 侧: True 列裁剪生效: True","why":"两条规则的要点：① 谓词下推只能推到 refs ⊆ 该侧 cols_out 的分支——本例只有 users 侧含 city，所以推到 users；如果谓词非确定（det=False）则一律不推。② 列裁剪是自顶向下求属性交集，Filter 的引用列必须计入子节点 need（否则会把过滤列裁掉），Join 的连接键也要计入两侧 need。真实 Spark 中这两条规则都在 Opt…"}],"works":[{"h":"以为 DataFrame 的 filter/select 会立刻执行","d":"错。DataFrame 与 RDD 一样是惰性的：transformation 只往逻辑计划里挂节点，只有 show/collect/count/write 等 action 才触发。正确写法：调试用 df.explain() 看计划，别在链式调用中间插 print(df.count()) 之类的 action，那会重复触发整条计划。"},{"h":"把 RDD 的 map(lambda ...) 习惯带进 DataFrame，用 UDF 包…","d":"错。lambda / Python UDF 对 Catalyst 是黑盒：无法谓词下推、无法列裁剪、还要付出 JVM ↔ Python 的序列化往返。正确写法：优先用内置函数（when/col/upper/substring 等）；必须用 UDF 时优先 Scala/Java UDF 或 Pandas UDF（向量化），并把它放在计划…"},{"h":"以为谓词下推一定会发生","d":"错。两条硬约束任一不满足就不下推：① 谓词必须确定性（含 rand()、current_timestamp() 的谓词不下推，因为下推会改变每行求值次数）；② 谓词引用的列必须在下方算子的输出列中（写在 Project 之后的过滤列若已被投影掉，则推不下去）。正确写法：把过滤尽量贴着数据源写，别先 select 掉过滤列再 filte…"},{"h":"把 where 写在子查询/视图之外，指望优化器救你","d":"错。Catalyst 确实会做谓词下推，但跨聚合（GROUP BY/DISTINCT）、跨 LIMIT、跨窗口函数的谓词下推受限，且一旦中间有 UDF、非确定性表达式或 outer join 的 null 侧，下推链就会断。正确写法：过滤条件尽量写在最靠近数据源的那一层；LEFT JOIN 里对右表的过滤条件写在 ON 后与写在 WH…"},{"h":"SELECT 导致列裁剪完全失效","d":"错。Catalyst 的列裁剪依赖「顶层真正需要哪些列」自顶向下传播；SELECT 使所有列都被标记为需要，Parquet 的向量化读就退化成全列读取。正确写法：只写需要的列；中间层视图也别 SELECT 。"},{"h":"以为分区裁剪自动生效","d":"错。分区裁剪（Partition Pruning）只对分区列生效，且要求过滤条件是「分区列 与 常量」的直接比较；dt = substr(other_col,1,10)、dt + 1 = '20260101' 这类对分区列做了变换的写法会让裁剪失效（Catalyst 无法反解）。正确写法：过滤条件写成 dt = '2026-01-01…"},{"h":"用 explain() 默认模式看计划，看不到关键细节","d":"错。df.explain() 默认只打印物理计划（且无格式化缩进），看不出逻辑计划优化前后的差异，也看不出 sizeInBytes 统计。正确写法：df.explain(mode=\"formatted\") 看缩进树；mode=\"extended\" 看 Parsed / Analyzed / Optimized / Physical 四…"},{"h":"读计划从上往下读","d":"错。执行计划树叶子是数据源、根是输出，物理执行自底向上。正确读法：① 先找所有 Scan（读了哪些表、哪些列、多少行）；② 看 Exchange（= 一次 Shuffle，是 Stage 边界）；③ 看 Join 的类型与 build 侧；④ 最后看 Aggregate 与输出。"}],"asks":[{"q":"Spark 为什么有了 RDD 还要引入 DataFrame？DataFrame 到底多给了 Spark 什么信息？","a":"核心答案是多给了两层信息，从而打开优化空间： 1. Schema（列名 + 类型）：Spark 知道数据有哪些列，才能做列裁剪——只读查询真正用到的列； 2. 逻辑计划（关系代数算子构成的语法树）：Spark 知道你要什么而不是怎么算，才能做等价重写——谓词下推、常量折叠、JOIN 重排、物理算子选择（广播 vs SortMerge）。 RDD 的计算函数是一个不透明闭包（lambda），Spar…","fu":["为什么 lambda 无法做等价重写？这与关系代数的等价律有什么关系？","DataFrame 和 Dataset 的区别是什么？PySpark 有 Dataset 吗？"],"tag":"通用/字节"},{"q":"讲一下 Catalyst 优化器的完整流程，以及 AnalysisException 是哪一阶段抛的？","a":"四个阶段 + 一个收尾： 1. 解析（Parsing）：ANTLR 做语法分析，生成未解析的语法树，此时列名与类型都还不知道； 2. 分析（Analysis / Binding）：查 Catalog（内存 Catalog 或 Hive Metastore）把列名、类型绑定上去，做类型检查； 列不存在、类型不匹配就在这一阶段抛 AnalysisException； 3. 逻辑优化（Logical O…","fu":["规则批（Rule / Batch）为什么要用不动点？如何保证终止？","CBO 的输入是什么？统计信息不准会导致什么后果？"],"tag":"通用/腾讯"},{"q":"谓词下推一定生效吗？什么情况下它不会下推？列裁剪又是什么时候失效？","a":"谓词下推的两条硬约束（任一不满足就不推）： 1. 谓词必须确定性——含 rand()、current_timestamp() 的谓词不下推。原因是下推会改变每行的求值次数与随机序列，破坏语义等价； 2. 谓词引用的列必须在下方算子的输出列内——若 Project 已把该列投影掉，就推不下去。 此外工程上常见的「推不动」：中间隔着 UDF / Python 算子等黑盒；对分区列做了函数变换（subs…","fu":["分区裁剪和谓词下推是一回事吗？两者的层次差异在哪？","LEFT JOIN 的右表过滤条件写在 ON 后和 WHERE 后，语义有什么不同？"],"tag":"通用/字节"},{"q":"Tungsten 做了什么？全阶段代码生成（Whole-Stage Codegen）解决的又是什么问题？","a":"Tungsten（内存与 CPU 层改造）三件事： 1. 紧凑二进制表示 UnsafeRow：8 字节 null 位图 + 每字段 8 字节定长区 + 8 字节对齐的变长区，字符串直接存 UTF-8 字节，没有对象头、没有装箱； 2. 堆外内存管理：用内存页（MemoryBlock，页号 + 偏移）管理堆外内存，绕过 JVM 对象分配与 GC； 3. 缓存友好的计算：按页批量处理，用 Unsafe…","fu":["为什么 Shuffle 会切断代码生成？","Whole-Stage Codegen 和向量化执行是什么关系？能叠加吗？"],"tag":"通用/阿里"}]},{"id":"bd-ch06","subj":"bigdata","title":"离线数仓实战：分层建模与调度","summary":"ODS/DWD/DWS/ADS 分层职责；维度建模与星型/雪花模型、缓慢变化维；指标口径一致性与数据质量校验；任务依赖与调度（DAG、补数、SLA）；一条端到端离线链路的拆解（采集 → 清洗 → 聚合 → 报表）；数据倾斜与资源调优的实战清…","concepts":[{"id":"bd-ch06/01-layered-warehouse","file":"01-layered-warehouse.md","title":"ODS / DWD / DWS / ADS：四层职责边界","kind":"flow","secs":[{"h":"二、分层落地规范：命名、调用约束与自动化体检","s":"（中立陈述）四层架构能不能立住，取决于有没有一套机器可检查的落地规范，而不是一本 PDF。三件必备的东西：","c":{"lang":"text","code":"ods_order_log              -- ODS，订单日志同步\ndwd_trade_order_detail_di  -- DWD，交易域订单明细，日增量(df/di/da)\ndws_trade_user_1d          -- DWS，交易域用户粒度的 1 日汇总\nads_gmv_overview           -- ADS，GMV 概览报表"}}]},{"id":"bd-ch06/02-dimensional-modeling","file":"02-dimensional-modeling.md","title":"事实表与维度表：粒度必须先声明","kind":"stack","secs":[{"h":"二、星型模型 vs 雪花模型：JOIN 次数与存储的定量取舍","s":"（中立陈述）维度可以以两种形态落地：","c":{"lang":"text","code":"粒度必须先声明（一行代表什么），否则所有指标都会错\n    事实表   度量 + 外键（订单明细：一行 = 一个 SKU 的一次购买）\n    维度表   描述性属性（用户、商品、时间、门店）\n\n    星型模型：事实表直接挂维度（查询简单、有冗余）\n    雪花模型：维度再规范化（省空间，多一层 join）\n\n    缓慢变化维（SCD）：\n      Type1  直接覆盖（丢历史）\n…"}}]},{"id":"bd-ch06/03-scd-and-metrics","file":"03-scd-and-metrics.md","title":"缓慢变化维 SCD：Type 1 / Type 2 / Type 3","kind":"flow","secs":[{"h":"二、指标口径治理：原子指标 / 派生指标与口径一致性","s":"（中立陈述）「两个报表上的 GMV 不一样」是数仓领域最经典的事故。根治办法是把指标规范化定义并集中管理。一套指标定义包含四要素：","c":{"lang":"python","code":"def check_metric_drift(spark, a_sql: str, b_sql: str, dt: str) -> dict:\n    \"\"\"同一指标被两处重写时，必须逐日对齐；差一点都是 bug，不是误差。\"\"\"\n    x = spark.sql(a_sql.format(dt=dt)).first()[0] or 0\n    y = spark.sql(b_sql.format(dt=dt)).first()[0] or 0\n    return {\"a\": x, \"b\": y, \"diff\": x - y, \"ok\": x == y}\n\n# 用法：把「报表 SQL」与「原子指标视图」跑同一天对比\nr = check_metric_drift(spark, REPORT_GMV, ATOMIC_GMV, \"2026-10-01\")\nassert r[\"ok\"], f\"口径已分叉：{r}\""}}]},{"id":"bd-ch06/04-scheduling-and-tuning","file":"04-scheduling-and-tuning.md","title":"任务依赖与调度：DAG、补数、SLA、幂等","kind":"timeline","secs":[{"h":"二、数据倾斜调优、元数据与数据血缘","s":"（中立陈述）数据倾斜是指：shuffle 后少数分区的记录数碾压其余分区。由于某个 key 的所有记录必然落入同一个分区（哈希分区），热 key 会让对应 reducer 成为唯一的长尾——整作业的完成时间由它决定。","c":{"lang":"text","code":"key 数 = 201，总记录数 = 67900，reducer 数 = 16\n【加盐前】最大分区=50879 中位数=1257.0 倾斜度=40.48   -> 判定倾斜\n【加盐后】最大分区=7372  中位数=4244.0 倾斜度=1.74    -> 不再倾斜（最慢 reducer 负载下降 6.9 倍）"}}]}],"exams":[{"kind":"choice","q":"ODS / DWD / DWS / ADS 的职责边界","stem":"某电商离线数仓每日凌晨跑一条从订单日志到管理层报表的链路。关于四层的职责，下列说法正确的是？","opts":[{"k":"A","t":"ODS 层会对业务库数据做深度业务清洗与维度整合，产出可直接分析的宽表"},{"k":"B","t":"DWD 层存放最细粒度的明细事实，是下游所有复用逻辑的共同基础"},{"k":"C","t":"DWS 层是面向某一张具体报表的最终结果表，口径可以直接写死"},{"k":"D","t":"ADS 任务可以直接覆盖写入 DWD 表的分区来快速修正数据"}],"ans":"B","why":"DWD 是清洗、标准化后的明细事实层，粒度最细、可被反复复用，说法正确。A 错：ODS 是业务库的原样镜像，不做业务清洗；C 错：DWS 面向主题域（交易/用户/流量），ADS 才面向具体应用；D 错：这是越层写入，会用高层逻辑污染低层数据，导致所有依赖该 DWD 表的下游一起出错。"},{"kind":"choice","q":"缓慢变化维 SCD Type 2 的必备机制","stem":"用户维度从「北京 / V1」在 2026-02-01 变为「北京 / V2」，在 2026-02-15 又迁到「上海 / V2」。采用 SCD Type 2 拉链表时，下列说法正确的是？","opts":[{"k":"A","t":"拉链表应为同一业务主键保留多行，并用代理键与事实表关联"},{"k":"B","t":"事实表应继续用业务主键 user_id 关联维表，靠 biz_date 过滤即可"},{"k":"C","t":"当前有效行的 end_date 应填为当天的日期，便于区间查询"},{"k":"D","t":"若某次变更的新属性与上一版本完全相同，也必须新增一行版本"}],"ans":"A","why":"Type 2 用「新增一行版本」保留历史，同一业务主键会有多行，因此必须引入代理键供事实表关联，A 正确。B 错：用业务主键 join 会导致事实表扇出（一笔事实匹配多个历史版本）。C 错：当前行的 end_date 必须用无穷大哨兵（业界惯用 9999-12-31），否则区间查询会漏掉当天之后的数据。D 错：属性无实质变化时不产生新版本（本章 ex02 实测 6 条变更合并为…"},{"kind":"choice","q":"事实表粒度违背与 join 扇出","stem":"订单明细表声明粒度为「一个订单的一个商品行」（粒度键 order_id + sku_id）。跑完后发现某个日期分区里 count() = 12000 而 count(distinct order_id, sku_id) = 11800。下列判断与对策正确的是？","opts":[{"k":"A","t":"属于正常现象，OLAP 明细表允许少量重复行"},{"k":"B","t":"粒度已被违背（粒度键不再是超码），应先定位重复来源，最常见是 join 时维表连接键不唯一造成扇出"},{"k":"C","t":"在最终聚合时加 DISTINCT 即可，不必追溯原因"},{"k":"D","t":"说明 src 侧数据本身有 200 条脏数据，直接删除即可"}],"ans":"B","why":"粒度声明等价于「粒度键是表的超码」，count() != count(distinct 粒度键) 就说明粒度已被违背。A 错：明细事实表不允许重复行。C 错：DISTINCT 只随机去掉重复行的表象，会把本该计入的金额一起删掉，导致 SUM 口径错误且难以发现。D 错：未定位原因就删数据是危险操作。正确对策是 join 前先把维表按连接键聚合到唯一。"},{"kind":"choice","q":"幂等重跑：INSERT OVERWRITE 与 INSERT INTO","stem":"ADS 任务在 02:00 执行失败一次，运维在 02:30 手动重跑了同一天的同一任务。该任务的写表语句是 INSERT INTO TABLE ads_gmv PARTITION(dt='2026-03-01')。预料的结果是？","opts":[{"k":"A","t":"分区仍是当天的正确结果，因为失败的那次没有写成功"},{"k":"B","t":"分区行数与金额合计翻倍（或增加失败那次残留的部分），说明写入方式不幂等"},{"k":"C","t":"分区被整分区替换，结果与跑一次完全相同"},{"k":"D","t":"调度系统会自动回滚失败的写入，无需关心"}],"ans":"B","why":"INSERT INTO 是 append（累积）语义，重跑会把同样的数据再追加一遍：本章 ex12 实测同一批 100 行数据跑两次得到 200 行、金额 395 → 790、产生 100 个重复粒度键。正确写法是 INSERT OVERWRITE TABLE t PARTITION(dt=...) —— put（赋值）语义，天然幂等；注意必须指定分区，否则会退化成全表覆盖的历…"},{"kind":"choice","q":"星型模型与雪花模型的取舍（Kimball 维度建模）","stem":"Kimball 维度建模体系中，关于星型模型与雪花模型的取舍，下列说法错误的是？","opts":[{"k":"A","t":"星型模型的维表冗余度高，查询所需 JOIN 更少，通常更适合 OLAP 场景"},{"k":"B","t":"雪花模型把维度层级规范化，节省存储且维度改名的影响面更小"},{"k":"C","t":"现代列式存储对重复值的压缩率很高，因此星型的冗余带来的实际磁盘代价往往远小于逻辑单元数差异"},{"k":"D","t":"雪花模型因为符合第三范式，所以在任何场景下都应该优先选择"}],"ans":"D","why":"D 的说法过于绝对，错误。本章 ex04 实测：同一查询星型只需 1 次 JOIN，雪花需 3 次；但雪花的维表单元总数 2220 小于星型的 3000，且部门改名的影响面是 10 行 vs 1000 行。工程上的标准结论是「默认星型，必要时部分雪花化」——OLAP 写多为整分区重建，规范化带来的更新异常防护收益有限，而 JOIN 成本是实打实的。"},{"kind":"coding","q":"调度依赖的环检测（LeetCode 207：Detected Cycle in Course Dependencies）","stem":"工程背景：调度系统要求任务依赖图必须是 DAG，否则无法确定执行顺序且会互相等待死锁。给定一个包含 n 个任务的调度列表，以及若干条依赖 [a, b]（表示任务 a 依赖任务 b），请判断这张依赖图能否拓扑排序（即是否无环）。 任务：实现 can_finish(n, prereq)，返回布尔值。要求用 Kahn 算法（入度表 + 就绪队列）或 DFS 三色标记，时间复杂度 O(n + m)。 >…","opts":[],"ans":"can_finish(2, [[1, 0]]) = True can_finish(2, [[1, 0], [0, 1]]) = False","why":"Kahn 算法的核心是反复剥离入度为 0 的节点。若最终已剥离的节点数 done < n，说明剩下的节点入度永远无法降到 0 —— 它们正处在（或依赖于）某个环上，因此图不可拓扑排序。这正是调度系统检测循环依赖的标准方法（本章 ex09 用例 B 误加回边后，Kahn 只排出了 0/10 个任务）。时间复杂度 O(n + m)，空间复杂度 O(n + m)。"},{"kind":"coding","q":"调度执行顺序求解（LeetCode 210：Topological Order of Tasks）","stem":"工程背景：调度系统每晚需要根据任务依赖生成一份执行顺序（可以并行的任务会被分到同一层，但对外仍需给出一个合法的线性序）。给定 n 个任务与依赖列表 [[a, b], ...]（a 依赖 b），请输出一个合法的执行顺序；若存在环则输出空列表。 任务：实现 task_order(n, prereq)，返回任务下标列表。为保证确定性，就绪队列每轮按下标升序取出。 > 本题来自 LeetCode 210（…","opts":[],"ans":"task_order(4, [[1, 0], [2, 0], [3, 1], [3, 2]]) = [0, 1, 2, 3] task_order(2, [[1, 0], [0, 1]]) = []","why":"拓扑排序可能有多解；生产环境为了可复现的日志与回放，通常用小顶堆（或排序）固定 tie-break 规则，这里按任务下标升序。存在环时 len(order) < n，按题意返回空列表。应用到数仓调度时，还要在拓扑序基础上叠加每个任务的运行时长做关键路径分析，才能得到整条链路的产出时间（见 ex09 / ex11）。复杂度 O((n + m) log n)。"},{"kind":"coding","q":"离线链路的关键路径、总浮动与最大并行度","stem":"给定一条离线数仓链路的任务字典（任务名 → 运行时长，整数时间单位）与依赖边列表 (上游, 下游)，实现三件事并打印： 1. 关键路径（makespan）：在 DAG 上做最长路 DP，求出整条链路的最短完成时间，并输出关键路径上的任务链； 2. 总浮动（slack）：对每个任务求 最晚开始 - 最早开始，并说明「只有 slack = 0 的任务提速才会缩短 makespan」； 3. 最大并行度…","opts":[],"ans":"关键路径用时 = 11 关键链 = ods_sync -> dwd_order -> dws_trade -> ads_kpi 总浮动 dwd_user = 1，总浮动 ads_item = 6 最大并行度 = 3","why":"三段 DP 都建立在拓扑序之上：① 正向递推 ES(v) = max(ES(u) + w(u)) 求最早开始（DAG 最长路，一般图上不可解，DAG 的无环性提供了阶段序）；② 反向递推求最晚开始，slack = LS - ES，slack 为 0 的节点构成关键路径；③ 用最早开始/完成区间做时间轴扫描得到最大并行度。工程含义：只有关键路径上的任务提速才会缩短整条链路的产出时…"}],"works":[{"h":"为了赶需求直接 SELECT FROM ods_xxx 出报表","d":"错。绕过 DWD/DWS 的报表会把业务库的字段语义直接耦合进报表；上游加一个枚举值、改一次时区语义，报表就会悄悄算错，且没有任何中间层能拦截。正确写法：任何面向业务的结果表都必须从 DWS/ADS 出发；确实只有 ODS 有数据时，先在 DWD 建一张规范化明细表再引用。"},{"h":"认为「分层只是命名习惯，跳一层没关系」","d":"错。分层单调性 ℓ(下游) ℓ(上游) ∈ {0,1} 是偏序，它保证依赖图天然无环、且层与层之间解耦。一旦允许任意跨层读写，边数从 O(n·k) 退化到 O(n²)，中间层没人维护，最终全部加工逻辑沉淀到报表层。正确写法：把「DWS 不得直接读 ODS」「ADS 不得反向写 DWD」写成可判定的检查，在 CI 里每天扫（见本章 ex…"},{"h":"ADS 任务直接 overwrite 一张 DWD 表的分区来「补数据」","d":"错。这是越层写入：越低层的数据被高层逻辑污染后，所有依赖这张 DWD 表的下游都会一起错，且事后难以界定谁改的。正确写法：从上游往下游重跑——先 backfill DWD 的历史分区，再依次重跑 DWS、ADS；紧急止血只能写 ADS 自己的临时表并限期回收。"},{"h":"建事实表时不写粒度声明","d":"错。粒度（一行代表什么）决定了这张表能回答什么问题、能否安全去重、能否做 SUM。没有粒度声明的表，半年后没人敢动，也找不到 MEASURE 膨胀的原因。正确写法：表注释第一行就写「本表粒度 = ...，粒度键 = ...，一行代表 ...」，并在每次跑完后校验 count() = count(distinct 粒度键)（见 ex05…"},{"h":"join 时发现行数变多，用 DISTINCT 或 row_number 兜住","d":"错。行数变多说明连接键在某侧不唯一，发生了扇出；加 DISTINCT 只是随机丢掉重复行，会把本该计入的金额一起删掉，造成数额错误且难以发现。正确写法：join 前先把维表按连接键聚合到唯一（GROUP BY key 取一个代表值），或先做一次 distinct(key) = count() 断言。"},{"h":"认为雪花模型「更规范所以更好」","d":"错。OLAP 场景读多写少、且写入往往是整表/整分区重建，因此 OLTP 关心的「更新异常」被重算过程自然消除；而 JOIN 次数的增加却是实打实的查询代价（实测 JOIN 从 1 次变 3 次）。正确写法：默认星型；只有维度层级深且需要跨维度共享时才部分雪花化，或干脆把常用层级物化成 DWS 宽表。"},{"h":"用 Type 1（覆盖）处理业务属性变更，事后又要回答「当时是什么」","d":"错。Type 1 的更新函数是非单射的，覆盖后历史状态不可从终态反推，这是不可逆的信息丢失（实测 5 笔历史订单答错 2 笔，按城市汇总 GMV 完全对不上）。正确写法：凡是需要历史回溯的属性（会员等级、客户归属、商品价格）一律 Type 2 拉链表。"},{"h":"Type 2 拉链表用业务主键做事实表的关联键","d":"错。同一业务主键在拉链表里有多行版本，用业务主键 join 会导致事实表扇出（一笔订单匹配多个历史版本，金额翻倍数 == 版本数）。正确写法：拉链表必须引入代理键（user_sk），事实表存代理键；join 时额外带上时间条件或直接 join 代理键。"}],"asks":[{"q":"数仓为什么要分层？ODS / DWD / DWS / ADS 各自的职责边界是什么？如果允许任意跨层读写会发生什么？","a":"为什么要分层（四点标准答案）： 1. 解耦：上游业务库改表结构只影响 ODS→DWD 这一跳，不用改下游几十个报表； 2. 复用：DWD 一旦做成干净的明细事实，成百上千的指标都从它出发，不必每个报表各自 join 一遍原始日志； 3. 口径统一：核心指标只在某一层定义一次，下游全部引用； 4. 问题定位：指标异常时可以逐层回溯，用跨层对账快速判断是采集丢了、清洗错了还是聚合算漏了。 职责边界：…","fu":["能不能省略 DWS，让 ADS 直接从 DWD 出？什么情况下可以简化？","如果发现某个 ADS 表直接读了 ODS，你会怎么改造这条链路？"],"tag":"通用/字节"},{"q":"什么是事实表的粒度？为什么建模第一步要先定粒度？粒度被违背通常是什么原因，怎么自动检出？","a":"粒度定义了「事实表的一行代表什么」，例如「一个订单里的一个商品行」（粒度键 order_id + sku_id）。 为什么第一步就要定：粒度决定了这张表能回答什么问题、能否安全去重、能否沿某维度做 SUM。形式化地说，粒度声明就是声明粒度键是该表的超码（粒度键 → 一行）。 什么时候会被违背（粒度键 不再是超码）：最常见的是 join 扇出 —— 连接键在维表那一侧不唯一（例如订单明细 join…","fu":["事务事实表 / 周期快照 / 累积快照三类事实表在重跑策略上有什么不同？","半可加度量（如库存量、账户余额）为什么沿时间不能 SUM？"],"tag":"通用/腾讯"},{"q":"星型模型和雪花模型怎么选？为什么说「现代 OLAP 场景默认星型」？","a":"差异（本章实测数据，按部门汇总销售额、层级 sku → cate → dept）： | 指标 | 星型 | 雪花 | |---|---|---| | 查询 JOIN 次数 | 1 | 3 | | 维表单元总数 | 3000 | 2220 | | 维度改名影响行数 | 1000 | 10 | 结论：雪花 JOIN 更多、查询更慢，但更省空间、一致性更好维护；星型用冗余换 JOIN 次数。 为什么默认…","fu":["星座模型（Fact Constellation）和星型、雪花有什么区别？","如果维表有 5000 万行，星型冗余还划算吗？"],"tag":"通用/字节"},{"q":"SCD Type 1 / Type 2 / Type 3 分别怎么处理维度变更？为什么 Type 2 必须用代理键？拉链表有哪些必须校验的不变式？","a":"| 类型 | 做法 | 保留历史 | 能否回答「当时是什么」 | 行数 | |---|---|---|---|---| | Type 1 | 直接覆盖 | 否 | 不能 | 不变 | | Type 2 | 新增版本行 + 有效期（拉链表） | 是 | 能 | 每次变更 +1 | | Type 3 | 新增「上一个值」列 | 仅最近一次 | 仅最近一次 | 不变 | 选型：纠正错误用 Type 1（…","fu":["上游只给日切快照、没有 CDC 变更前/后镜像时，怎么构造拉链表？有什么坑？","一天内同一个 key 变了两次，拉链表会漏吗？怎么发现？"],"tag":"阿里/字节"}]}];

